    // 2. THE ROOT IS A TABLE, and its size is the record's body
    if (kind(0) != 13) {
      refusal = TableFixedRefusal.layoutKindInvalid;
      count = 0;
      return false;
    }
    if (size(0) == 0 || size(0) > TableFixedLimits.recordMaxBytes) {
      refusal = TableFixedRefusal.layoutRecordTooLarge;
      count = 0;
      return false;
    }
    // 3. EVERY KIND IN THE CLOSED SET AND USED AS ITS DEFINITION ALLOWS, EVERY
    //    SIZE THE ONE ITS CHILDREN ACCOUNT FOR, NOTHING PAST THE WALK'S BOUND
    final used = checkEntry(0, 0);
    if (refusal != TableFixedRefusal.none) {
      count = 0;
      return false;
    }
    // 4. THE PRE-ORDER WALK CONSUMES EXACTLY THE ENTRIES: the tree closes and
    //    the layout has nothing left over
    if (used != count) {
      refusal = TableFixedRefusal.layoutTreeUnclosed;
      count = 0;
      return false;
    }
    return true;
  }
}

/// THE PLAN'S STORAGE IS THE CALLER'S, DECLARED BY CAPACITY, AND THE CODEC
/// NEVER ALLOCATES. A caller makes one of these per endpoint and hands it in; a
/// layout whose plan does not fit is a refusal by name, never a growth.
final class TableFixedPlan {
  TableFixedPlan(int entryCapacity, int imageBytes, int remapCapacity)
    : entries = Int32List(entryCapacity * TableFixedLane.lanes),
      capacity = entryCapacity,
      image = Uint8List(imageBytes),
      fill = Int32List((imageBytes + 1) * 2),
      remap = Int32List(remapCapacity) {
    imageView = ByteData.sublistView(image);
  }

  final Int32List entries;
  final int capacity;
  int count = 0;

  /// the reader's own storage: this build's declared order at its own widths
  final Uint8List image;
  late final ByteData imageView;

  /// THE PREFILL'S RANGES, packed (dst, size) once when the plan is compiled.
  /// Identity's count is zero — empty list is the skip, not a flag.
  final Int32List fill;
  int fillCount = 0;

  /// the remap tables an ordinal entry resolves through, laid down here rather
  /// than above the entries: Dart has no pointer to alias two lists through,
  /// so the pool is its own list and aux is an index into it
  final Int32List remap;
  int remapUsed = 0;

  /// THE CURRENT UNION'S TAG WIDTH, stamped onto every entry the walk pushes
  /// beneath it (§5.2, THE GUARD'S WIDTH). One outside a union, and the union
  /// case saves it, sets its own and restores it, so a nested union's arms carry
  /// their OWN tag's width.
  int argw = 1;

  /// THE GUARD CHAIN of the arm being compiled, OUTERMOST FIRST (§4.1): one
  /// (guard, arg, argw) link per enclosing union, pushed on the way into an arm
  /// and popped on the way out; chainAt is where it was laid in the pool, once
  /// per arm, or -1. Sized once for the layout's 64.
  final Int32List chain = Int32List(65 * 3);
  int chainLen = 0;
  int chainAt = -1;

  /// THE TWO-PASS SPLIT (§5.2, §5.9 #42). The walk runs TWICE — unguarded
  /// entries first, guarded ones second — and split is the index the guarded
  /// half starts at. pass is which half the walk is keeping, tested at the
  /// PUSH so a kind that allocates from the pool before it pushes does not
  /// spend it twice. The split is what puts a union's unguarded None tag AHEAD
  /// of the arm that overwrites it; the coalescer never merges across it.
  int pass = 0;
  int split = 0;

  /// an enum's remap, built here and then laid down; a scratch of the plan and
  /// never of the loop
  final Int32List remapScratch = Int32List(256);

  /// the two layout views a compile needs, held here so a compile allocates
  /// nothing either. THE LOAD PATH USES NEITHER ANY MORE (§5): the plans are
  /// the BUILD's, and these are what a BUILD-time compile parses the LOCK'S
  /// bytes into.
  final TableFixedLayout theirs = TableFixedLayout();
  final TableFixedLayout mine = TableFixedLayout();

  /// THESE FOUR ARE THE PLAN-CACHE LANES, and §5.6 retires the MECHANISM and
  /// not the API (§5.9 #16, #24): a load no longer writes one of them — it
  /// selects by hash against the lineage and never compiles — and they stay
  /// here so every caller that holds a plan still compiles. A leg that started
  /// reading them again would have un-retired the run-time compile.
  int recordBytes = 0;
  int hash = 0;
  bool ready = false;
  bool overflow = false;

  /// the WRITER's declared root size — the bound every entry's source extent
  /// is held to (§5.2): an entry that reached past it would read the NEXT
  /// record's bytes
  int record = 0;

  /// ONE ENTRY PAST THE WRITER'S RECORD, which refuses the plan WHOLE under
  /// layout_record_too_large (§5.2) and never lands a short read
  bool tooLarge = false;

  /// the sixteen-byte conversion scratch the float rung widens through
  final ByteData conv = ByteData(16);
}

/// A CACHE BY HASH: "the cost of the compile is paid once per endpoint rather than
/// once per record". The caller owns this too — and under §5 THERE IS NOTHING
/// LEFT TO CACHE: every plan is laid down by the build from the lock's bytes,
/// so no load compiles and no load can miss. The type stays because §5.6
/// retires MECHANISMS and not API (§5.9 #16): a caller holding one still
/// compiles, and the codec never reads it.
final class TableFixedPlanCache {
  final Map<int, TableFixedPlan> plans = <int, TableFixedPlan>{};

  TableFixedPlan? get(int hash) => plans[hash];

  TableFixedPlan put(int hash, TableFixedPlan plan) {
    plans[hash] = plan;
    return plan;
  }
}

/// ONE LOCKED LAYOUT (docs/FIXED-FORM-ALGORITHM.md §5.2's static data, the four
/// members of §5.9 #19 in that order): the WIRE HASH a file is matched on, the
/// layout BYTES verbatim, that run's BYTE LENGTH riding beside them, and the
/// RECORD SIZE taken from the lock and never from the file.
final class TableFixedKnownLayout {
  const TableFixedKnownLayout(
    this.hash,
    this.layout,
    this.layoutBytes,
    this.recordBytes,
  );

  final int hash;
  final Uint8List layout;
  final int layoutBytes;
  final int recordBytes;
}

/// THE FIRST lineage index whose hash is the file's, or -1 for a hash no entry
/// holds. A file is matched on THIS and on nothing else (§5.3 step 5).
int tableFixedSelect(List<TableFixedKnownLayout> known, int hash) {
  for (var i = 0; i < known.length; i++) {
    if (known[i].hash == hash) {
      return i;
    }
  }
  return -1;
}

/// ONE OLDER ENTRY'S PLAN, laid down from THE LOCK'S BYTES and never from a
/// file's. 'unknown' and 'kindMismatch' are the COMPILE CENSUS — the plan's own
/// numbers, carried onto a report ONCE after the record loop and only on a read
/// that returns (§5.4, §5.9 #6). 'why' is the name an entry the lock got wrong
/// refuses by, so a bad entry still answers by name rather than by a throw
/// (§5.9 #8).
final class TableFixedLineagePlan {
  TableFixedLineagePlan(
    this.entries,
    this.count,
    this.fill,
    this.fillCount,
    this.remap,
    this.unknown,
    this.kindMismatch,
    this.why,
  );

  final Int32List entries;
  final int count;
  final Int32List fill;
  final int fillCount;
  final Int32List remap;
  final int unknown;
  final int kindMismatch;
  final int why;
}

/// ONE PLAN PER LINEAGE ENTRY, BUILT FROM THE LOCK'S OWN BYTES. A Dart
/// top-level 'final' is initialised LAZILY, ONCE PER ISOLATE, which is §5.9 #3's
/// build time for a language with no 'constexpr': the bytes came from the lock,
/// the walk happens once per process, a plan that will not build is a build
/// fault rather than a refusal at the first file that needs it, and THE LOAD
/// PATH COMPILES NOTHING AND PARSES NO LAYOUT A FILE CARRIED. There is no cache
/// a load can miss. The identity entry keeps an empty lane: the baked plan
/// answers it.
List<TableFixedLineagePlan> tableFixedLineagePlans(
  List<TableFixedKnownLayout> known,
  Uint8List myLayout,
  Int32List myDst,
  Int32List cover,
  int coverCount,
  int imageBytes,
  int ownHash,
) {
  final empty = Int32List(0);
  final out = <TableFixedLineagePlan>[];
  for (final k in known) {
    if (k.hash == ownHash) {
      out.add(
        TableFixedLineagePlan(
          empty,
          0,
          empty,
          0,
          empty,
          0,
          0,
          TableFixedRefusal.none,
        ),
      );
      continue;
    }
    // THE SIZE IS DISCOVERED BY CONSTRUCTION (§5.9 #4): the build grows its
    // own scratch until the plan fits and stops at a declared cap, and an
    // entry past that cap records 'plan_too_large' ON THAT ENTRY (§5.9 #5).
    var lane = TableFixedLineagePlan(
      empty,
      0,
      empty,
      0,
      empty,
      0,
      0,
      TableFixedRefusal.planTooLarge,
    );
    for (var room = 256; room <= 1 << 18; room *= 4) {
      final plan = TableFixedPlan(room, imageBytes, 1024 + 32 * room);
      if (!plan.theirs.parse(
        ByteData.sublistView(k.layout),
        0,
        k.layoutBytes,
      )) {
        // A LINEAGE ENTRY THAT IS NOT A LAYOUT IS A BUG IN THE LOCK and never
        // a wire event; where it arrives at run time the entry still owes a
        // name rather than a throw (§5.9 #8, #26).
        lane = TableFixedLineagePlan(
          empty,
          0,
          empty,
          0,
          empty,
          0,
          0,
          TableFixedRefusal.layoutMalformed,
        );
        break;
      }
      final census = TableFixedReport();
      final made = TableFixedCompiler.compile(
        plan,
        myLayout,
        ByteData.sublistView(myLayout),
        myDst,
        cover,
        coverCount,
        census,
      );
      if (made == -3) {
        // ONE ENTRY PAST THE WRITER'S DECLARED RECORD (§5.2, fix 3): the
        // plan refuses WHOLE under layout_record_too_large and a bigger room
        // cannot fix it, so the entry's lane says so and the load that
        // selects it refuses by that name.
        lane = TableFixedLineagePlan(
          empty,
          0,
          empty,
          0,
          empty,
          0,
          0,
          TableFixedRefusal.layoutRecordTooLarge,
        );
        break;
      }
      if (made < 0) {
        continue;
      }
      lane = TableFixedLineagePlan(
        Int32List.fromList(
          plan.entries.sublist(0, made * TableFixedLane.lanes),
        ),
        made,
        Int32List.fromList(plan.fill.sublist(0, plan.fillCount * 2)),
        plan.fillCount,
        Int32List.fromList(plan.remap.sublist(0, plan.remapUsed)),
        census.unknown,
        census.kindMismatch,
        TableFixedRefusal.none,
      );
      break;
    }
    out.add(lane);
  }
  return out;
}

/// THE TAG IS COMPARED AT ITS OWN WIDTH. A two- or four-byte tag whose LOW
/// BYTE happens to be 1 is not arm 1: it is an ordinal this build has no arm
/// for, and reading only the first byte let a foreign tag of 0x0101 run arm 1's
/// entries over a stranger's record (§5.2, THE GUARD'S WIDTH; §7 fix 12).
/// ArgW is clamped to 1..8 at both ends and ZERO READS AS ONE, because one is
/// the width a tag had when this lane did not exist, so a plan laid down before
/// it still reads.
int tableFixedTagAt(Uint8List source, int at, int argw) {
  var w = argw;
  if (w <= 0) {
    w = 1;
  } else if (w > 8) {
    w = 8;
  }
  var v = 0;
  for (var i = 0; i < w; i++) {
    v |= source[at + i] << (8 * i);
  }
  return v;
}

/// THE ONE READ LOOP. A READ IS A PREFILL AND THIS LOOP, AND NOTHING ELSE.
/// Which plan it is handed is the only thing that differs between reading this
/// build's own record and reading anybody else's — the owner's ruling, which
/// §3.4 quotes him on: a form whose cost moved when an endpoint shipped would be a
/// performance cliff at exactly the moment a deployment cannot afford one.
///
/// A RUN IS A SMALL, KNOWN NUMBER OF BYTES. The C++ reference writes the copy
/// as overlapping unaligned word moves because a runtime-length memcpy per
/// entry costs it the measurement the one-reader ruling rests on; the fastest
/// move Dart has for the same job is Uint8List.setRange, which is the typed
/// list's own bulk copy and not a per-byte loop, so that is what this is.
///
/// THE RUN ANSWERS THE REFUSAL IT FOUND, or TableFixedRefusal.none. A text
/// entry whose USED units are not the text its kind says REFUSES THE READ BY
/// NAME (§4.5 fix 11): the length still clamps and counts, but the content
/// check runs on the units it kept and a violation returns text_ill_formed
/// before the length or a unit byte is written, so REFUSE moves no counter and
/// lands nothing.
int tableFixedRun(
  Int32List plan,
  int entryCount,
  Uint8List source,
  ByteData sourceView,
  int at,
  Uint8List image,
  ByteData imageView,
  Int32List remap,
  ByteData conv,
  TableFixedReport report,
) {
  for (var i = 0; i < entryCount; i++) {
    final b = i * TableFixedLane.lanes;
    final guard = plan[b + TableFixedLane.guard];
    // an entry belonging to an ARM runs only under its own tag, compared at
    // ArgW bytes and never as a prefix
    if (guard != tableFixedNoGuard &&
        tableFixedTagAt(source, at + guard, plan[b + TableFixedLane.argW]) !=
            plan[b + TableFixedLane.arg]) {
      continue;
    }
    // AN ARM INSIDE AN ARM ANSWERS TO EVERY OUTER TAG TOO (§4.1, the guard
    // chain): the links outside the innermost, outermost first, all must hold.
    final links = plan[b + TableFixedLane.guardCount];
    if (links > 1) {
      var holds = true;
      var g = plan[b + TableFixedLane.guards];
      for (var j = 0; j < links - 1; j++, g += 3) {
        if (tableFixedTagAt(source, at + remap[g], remap[g + 2]) != remap[g + 1]) {
          holds = false;
          break;
        }
      }
      if (!holds) {
        continue;
      }
    }
    final s = at + plan[b + TableFixedLane.src];
    final d = plan[b + TableFixedLane.dst];
    final size = plan[b + TableFixedLane.size];
    switch (plan[b + TableFixedLane.op]) {
      case TableFixedOp.copy:
        image.setRange(d, d + size, source, s);
        break;
      case TableFixedOp.count:
        var counted = sourceView.getInt32(s, Endian.little);
        if (counted < 0) {
          counted = 0;
          report.clamped++;
        } else if (counted > size) {
          counted = size;
          report.clamped++;
        }
        imageView.setInt32(d, counted, Endian.little);
        break;
      case TableFixedOp.text:
        final cap = size;
        var used = sourceView.getInt32(s, Endian.little);
        var clampFired = false;
        if (used < 0) {
          used = 0;
          clampFired = true;
        } else if (used > cap) {
          used = cap;
          clampFired = true;
        }
        // THE CONTENT RULES APPLY TO THE USED UNITS AND NOTHING ELSE, and a
        // violation REFUSES BY NAME (§4.5 fix 11): the length above clamps and
        // counts, but THE CHECK RUNS FIRST, over the units it kept and never
        // over the slack, so a refusal moves no counter and writes no byte.
        if (tableFixedTextIllFormed(
          plan[b + TableFixedLane.meta],
          used,
          source,
          s + 4,
        )) {
          return TableFixedRefusal.textIllFormed;
        }
        if (clampFired) {
          report.clamped++;
        }
        imageView.setInt32(d, used, Endian.little);
        image.setRange(
          plan[b + TableFixedLane.aux],
          plan[b + TableFixedLane.aux] + size,
          source,
          s + 4,
        );
        break;
      case TableFixedOp.ordinal:
        // A VARIANT ORDINAL IS ITS POSITION IN THE LAYOUT, so a writer whose
        // enum gained a variant IN THE MIDDLE is remapped here and never
        // reinterpreted.
        // AND THE ORDINAL IS UNSIGNED. A Dart int is 64-bit SIGNED, so an
        // eight-byte ordinal with the high bit set — 0x8000000000000000 — comes
        // out of this loop NEGATIVE, and a signed 'raw <= table[0]' then passes
        // it straight into the remap as a NEGATIVE INDEX: a RangeError thrown
        // out of the read loop at hostile bytes, which is the one thing the
        // forgery oracle refuses (§5.4, §5.9 #8). Any raw the WRITER could not
        // have written — past its variant count, the negative case included —
        // is None AND COUNTED, on this plan exactly as on the identity one.
        var raw = 0;
        for (var k = 0; k < size; k++) {
          raw |= source[s + k] << (8 * k);
        }
        final remapAt = plan[b + TableFixedLane.aux];
        var landed = 0;
        if (raw < 0 || raw > remap[remapAt]) {
          report.clamped++;
        } else if (raw != 0) {
          landed = remap[remapAt + raw];
        }
        final ordinalWidth = plan[b + TableFixedLane.meta] & 0xff;
        for (var k = 0; k < ordinalWidth; k++) {
          image[d + k] = (landed >>> (8 * k)) & 0xff;
        }
        break;
      case TableFixedOp.widen:
        // TWO'S COMPLEMENT WIDENS BY ITS SIGN BIT, which is the whole reason a
        // widen is an op and not a short copy.
        final wideWidth = plan[b + TableFixedLane.meta] & 0xff;
        final signed = (plan[b + TableFixedLane.meta] >>> 8) & 1;
        var fill = 0;
        if (signed != 0 && (source[s + size - 1] & 0x80) != 0) {
          fill = 0xff;
        }
        for (var k = 0; k < wideWidth; k++) {
          image[d + k] = k < size ? source[s + k] : fill;
        }
        report.widened++;
        break;
      case TableFixedOp.widenFloat:
        // widenF IS THE ORDINARY CONVERSION (§4's float rung, §5.2's table;
        // docs/SPEC-TABLES.md §3.3): exact for every finite float32. A NaN
        // stays a NaN and an infinity an infinity, and the decode's raw-bits
        // test on the widened cell refuses either as non_finite_float.
        conv.setFloat64(
          0,
          sourceView.getFloat32(s, Endian.little),
          Endian.little,
        );
        for (var k = 0; k < 8; k++) {
          image[d + k] = conv.getUint8(k);
        }
        report.widened++;
        break;
      case TableFixedOp.constant:
        final value = plan[b + TableFixedLane.aux];
        for (var k = 0; k < size; k++) {
          image[d + k] = (value >>> (8 * k)) & 0xff;
        }
        // AN UNGUARDED None CONST CARRIES THE WRITER'S ARM COUNT in meta: a tag
        // PAST that set lands None — already written, just above — and COUNTS,
        // which is the same landing the identity plan's decode gives it (§5.4).
        // THE TAG IS READ UNSIGNED: a Dart int is 64-bit signed, so an
        // eight-byte tag with the high bit set is negative here and a signed
        // '>' would pass it as if it named an arm.
        final arms = plan[b + TableFixedLane.meta];
        if (value == 0 && arms != 0 && guard == tableFixedNoGuard) {
          final raw = tableFixedTagAt(source, s, size);
          if (raw < 0 || raw > arms) {
            report.clamped++;
          }
        }
        break;
      case TableFixedOp.present:
        // T INTO ?T: the reader's PRESENT byte, a constant 1. It moves no
        // counter — the op lands its value and nothing happened (§5.4).
        image[d] = 1;
        break;
      default:
        break;
    }
  }
  return TableFixedRefusal.none;
}

/// tableFixedTextIllFormed reports whether a text payload's USED units are the
/// text its kind says (docs/FIXED-FORM-ALGORITHM.md §4.5 fix 11, §5.4):
/// well-formed UTF-8 with no zero byte for string(N). bytes(N) carries no
/// content rule at all, and the SLACK past the used bytes is unspecified and
/// never a refusal. used is the clamped length; at is the first byte.
bool tableFixedTextIllFormed(int meta, int used, Uint8List source, int at) {
  if (meta == TableFixedOp.textBytes) {
    return false;
  }
  // UTF-8 over the used BYTES: the shortest form of each sequence, no
  // continuation byte out of place, no zero byte anywhere, and no code point
  // a UTF-8 scalar cannot be — an overlong form, a surrogate encoded in UTF-8,
  // or a point past U+10FFFF is each ill-formed (docs/SPEC-TABLES.md §3.4's
  // ill-formed set). The scalar ranges mirror the packet reader's
  // (internal/codegen/dart/utf8.go).
  bool cont(int k) => (source[at + k] & 0xC0) == 0x80;
  var i = 0;
  while (i < used) {
    final c = source[at + i];
    if (c == 0) {
      return true;
    } else if (c < 0x80) {
      i++;
    } else if ((c & 0xE0) == 0xC0) {
      if (c < 0xC2 || i + 1 >= used || !cont(i + 1)) {
        return true;
      }
      i += 2;
    } else if ((c & 0xF0) == 0xE0) {
      if (i + 2 >= used || !cont(i + 1) || !cont(i + 2)) {
        return true;
      }
      final point =
          ((c & 0x0F) << 12) |
          ((source[at + i + 1] & 0x3F) << 6) |
          (source[at + i + 2] & 0x3F);
      if (point < 0x800 || (point >= 0xD800 && point <= 0xDFFF)) {
        return true;
      }
      i += 3;
    } else if ((c & 0xF8) == 0xF0) {
      if (i + 3 >= used || !cont(i + 1) || !cont(i + 2) || !cont(i + 3)) {
        return true;
      }
      final point =
          ((c & 0x07) << 18) |
          ((source[at + i + 1] & 0x3F) << 12) |
          ((source[at + i + 2] & 0x3F) << 6) |
          (source[at + i + 3] & 0x3F);
      if (point < 0x10000 || point > 0x10FFFF) {
        return true;
      }
      i += 4;
    } else {
      return true;
    }
  }
  return false;
}

/// THE PREFILL ITSELF: the declared defaults, into the ranges named and
/// nowhere else. Empty count is the skip — identity's list is empty because
/// its destinations ARE the value bytes, so there is nothing left to subtract.
void tableFixedFillRun(
  Int32List fill,
  int count,
  Uint8List defaults,
  Uint8List dst,
) {
  for (var i = 0; i < count; i++) {
    final o = fill[i * 2];
    final n = fill[i * 2 + 1];
    dst.setRange(o, o + n, defaults, o);
  }
}

/// THE PLAN COMPILER. The SAME LOOP runs over this plan as over the identity
/// plan. What the compiler does, ONCE PER ENDPOINT, is what a read would otherwise
/// do once per record: map the writer's ids onto this reader's fields; leave a
/// field it cannot name OUT of the plan, which is what skips it, by arithmetic
/// that was going to step past it anyway; and leave a field the writer does
/// not carry out too, which is what defaults it, because the compiler's fill
/// list names those bytes and the load copies the declared default there.
///
/// THE PLAN IS COMPILED ONLY AFTER THE LAYOUT HAS PASSED EVERY RULE, so no
/// arithmetic here is ever performed on a size or a child count a stranger
/// chose and nobody checked.
abstract final class TableFixedCompiler {
  /// §4'S WIDENING RUNGS, and the fixed form spends no rule of its own on
  /// them: a kind that GREW since the writer decodes at the writer's width and
  /// lands exactly, counting one widened. Coming back DOWN the ladder, or
  /// across two of them, is a kind that MOVED and is reported rather than
  /// reinterpreted.
  /// THE WIDENING LADDER RUNS INSIDE A FAMILY AND UPWARD ONLY (§1): 2..5,
  /// 6..9, 20..24 the SIGNED fixed(I,F) run, 25..29 the UNSIGNED one, and
  /// 10 -> 11. So u8 into i32 is a kind that MOVED and is reported, never a
  /// widen.
  static bool widens(int from, int to) {
    if (from >= 6 && from <= 9 && to >= 6 && to <= 9) {
      return to > from; // u8 .. u64
    }
    if (from >= 2 && from <= 5 && to >= 2 && to <= 5) {
      return to > from; // i8 .. i64
    }
    if (from >= 20 && from <= 24 && to >= 20 && to <= 24) {
      return to > from; // fixed(I,F) SIGNED, at 8/16/32/64/128 storage bits
    }
    if (from >= 25 && from <= 29 && to >= 25 && to <= 29) {
      return to > from; // ufixed(I,F) UNSIGNED, the same five widths
    }
    return from == 10 && to == 11; // f32 -> f64
  }

  /// A LADDER WIDEN'S SIGN IS THE WRITER'S KIND'S: the signed integers and a
  /// SIGNED fixed-point sign-extend, everything else zero-extends. The
  /// SAME-KIND widen has no sign at all and zero-extends (§5.2).
  static bool signedKind(int kind) =>
      (kind >= 2 && kind <= 5) || (kind >= 20 && kind <= 24);

  /// THE TWO-PASS SPLIT (§5.2, §5.9 #42): pass 0 keeps the UNGUARDED entries,
  /// pass 1 the guarded ones. A kind that ALLOCATES from the pool before it
  /// pushes — the enum, whose remap table is laid down — must test the half
  /// FIRST, or the discarded pass still spends the pool and a plan that fits
  /// comes back plan_too_large.
  static bool keeping(TableFixedPlan plan, int guard) =>
      plan.pass == 0 ? guard == tableFixedNoGuard : guard != tableFixedNoGuard;

  /// THE LAST SOURCE BYTE, exclusive, an entry reads — the guard included,
  /// because a guarded entry loads the tag before anything else. The bound it
  /// is held to is the WRITER's declared root size (§5.2), and never this
  /// reader's: an entry that reached past it would read the NEXT record's
  /// bytes.
  static int srcEnd(int op, int src, int size, int aux, int guard, int argw) {
    var end = 0;
    switch (op) {
      case TableFixedOp.constant:
        // a constant reads no source at all — EXCEPT the union's None const,
        // which reads the writer's raw tag to count a clamp past its arm set
        if (aux == 0 && size != 0) {
          end = src + size;
        }
        break;
      case TableFixedOp.count:
        end = src + 4; // size is the BOUND, not a byte count
        break;
      case TableFixedOp.text:
        end = src + 4 + size;
        break;
      default:
        end = src + size;
    }
    if (guard != tableFixedNoGuard) {
      final w = argw <= 0 ? 1 : (argw > 8 ? 8 : argw);
      final g = guard + w;
      if (g > end) {
        end = g;
      }
    }
    return end;
  }

  static void push(
    TableFixedPlan plan,
    int op,
    int src,
    int dst,
    int size,
    int aux,
    int guard,
    int arg,
    int meta,
  ) {
    // THE HALF IS TESTED AT THE PUSH, so the two walks push the same pairs and
    // each keeps only its own.
    if (!keeping(plan, guard)) {
      return;
    }
    // ONE ENTRY PAST THE WRITER'S RECORD REFUSES THE PLAN WHOLE (§5.2). The
    // bound is the writer's declared root size and not this reader's: an
    // entry that reached past it would read the NEXT record's bytes, so the
    // plan is refused under layout_record_too_large rather than landed short.
    final end = srcEnd(op, src, size, aux, guard, plan.argw);
    if (plan.record != 0 && end > plan.record) {
      plan.tooLarge = true;
      return;
    }
    if (plan.count >= plan.capacity) {
      plan.overflow = true;
      return;
    }
    final b = plan.count * TableFixedLane.lanes;
    final e = plan.entries;
    e[b + TableFixedLane.op] = op;
    e[b + TableFixedLane.src] = src;
    e[b + TableFixedLane.dst] = dst;
    e[b + TableFixedLane.size] = size;
    e[b + TableFixedLane.aux] = aux;
    e[b + TableFixedLane.guard] = guard;
    e[b + TableFixedLane.arg] = arg;
    e[b + TableFixedLane.meta] = meta;
    // argw IS THE GUARD'S WIDTH IN BYTES, and zero reads as one.
    e[b + TableFixedLane.argW] = plan.argw <= 0 ? 1 : plan.argw;
    e[b + TableFixedLane.guards] = 0;
    e[b + TableFixedLane.guardCount] = 0;
    // THE GUARD CHAIN (§4.1): an entry beneath a union answers to EVERY
    // enclosing tag. Its guard lane is the chain's innermost link, and a chain
    // past one is laid into the pool, once per arm, as offset+count.
    if (guard != tableFixedNoGuard && plan.chainLen > 0) {
      final c = plan.chain;
      final inner = (plan.chainLen - 1) * 3;
      e[b + TableFixedLane.guard] = c[inner];
      e[b + TableFixedLane.arg] = c[inner + 1];
      e[b + TableFixedLane.argW] = c[inner + 2];
      if (plan.chainLen > 1) {
        if (plan.chainAt < 0) {
          final need = plan.chainLen * 3;
          if (plan.remapUsed + need > plan.remap.length) {
            plan.overflow = true;
            return;
          }
          plan.chainAt = plan.remapUsed;
          for (var k = 0; k < need; k++) {
            plan.remap[plan.chainAt + k] = c[k];
          }
          plan.remapUsed += need;
        }
        e[b + TableFixedLane.guards] = plan.chainAt;
        e[b + TableFixedLane.guardCount] = plan.chainLen;
      }
    }
    plan.count++;
  }

  static int layRemap(TableFixedPlan plan, Int32List values, int n) {
    final need = n + 1;
    if (plan.remapUsed + need > plan.remap.length) {
      plan.overflow = true;
      return 0;
    }
    final at = plan.remapUsed;
    plan.remap[at] = n;
    for (var i = 0; i < n; i++) {
      plan.remap[at + 1 + i] = values[i];
    }
    plan.remapUsed += need;
    return at;
  }

  /// matchChildren walks a TABLE's children on both sides, by id.
  static void matchChildren(
    TableFixedPlan plan,
    int ti,
    int theirAt,
    int mi,
    Int32List dst,
    int myAt,
    int guard,
    int arg,
    TableFixedReport report,
    bool census,
  ) {
    final theirs = plan.theirs;
    final mine = plan.mine;
    final theirChildren = theirs.children(ti);
    final myChildren = mine.children(mi);
    var myChild = mi + 1;
    for (var k = 0; k < myChildren; k++) {
      var theirChild = ti + 1;
      var theirOff = theirAt;
      for (var j = 0; j < theirChildren; j++) {
        if (theirs.id(theirChild) == mine.id(myChild)) {
          compileEntry(
            plan,
            theirChild,
            theirOff,
            myChild,
            dst,
            myAt,
            guard,
            arg,
            report,
            census,
          );
          break;
        }
        theirOff += theirs.size(theirChild);
        theirChild += theirs.subtree(theirChild);
      }
      myChild += mine.subtree(myChild);
    }
    // EVERY FIELD OF THEIRS I COULD NOT NAME IS ONE unknown
    var tc = ti + 1;
    for (var j = 0; j < theirChildren; j++) {
      var named = false;
      var mc = mi + 1;
      for (var k = 0; k < myChildren; k++) {
        if (mine.id(mc) == theirs.id(tc)) {
          named = true;
          break;
        }
        mc += mine.subtree(mc);
      }
      if (!named && census) {
        report.unknown++;
      }
      tc += theirs.subtree(tc);
    }
  }

  static void compileEntry(
    TableFixedPlan plan,
    int ti,
    int theirAt,
    int mi,
    Int32List dst,
    int myAt,
    int guard,
    int arg,
    TableFixedReport report,
    bool census,
  ) {
    final theirs = plan.theirs;
    final mine = plan.mine;
    final theirKind = theirs.kind(ti);
    final myKind = mine.kind(mi);
    final theirSize = theirs.size(ti);
    final mySize = mine.size(mi);
    final row = mi * TableFixedLane.dstLanes;
    final at = myAt + dst[row + TableFixedLane.dstOffset];
    final auxAt = myAt + dst[row + TableFixedLane.dstAux];
    // T INTO ?T (§5.2's EMIT, bill §12.8): the reader wraps what the writer
    // sent plain. The PRESENT byte is a constant 1 — constant in its VALUE and
    // still carrying the row's own guard and ordinal (§5.9 #13), so an optional
    // under a union arm never reports present for an arm the tag did not name —
    // and then the payload lands under that same guard.
    if (myKind == 35 && theirKind != 35) {
      push(plan, TableFixedOp.present, theirAt, auxAt, 1, 0, guard, arg, 0);
      compileEntry(
        plan,
        ti,
        theirAt,
        mi + 1,
        dst,
        myAt,
        guard,
        arg,
        report,
        census,
      );
      return;
    }
    if (theirKind != myKind) {
      if (widens(theirKind, myKind)) {
        final op = theirKind == 10
            ? TableFixedOp.widenFloat
            : TableFixedOp.widen;
        push(
          plan,
          op,
          theirAt,
          at,
          theirSize,
          0,
          guard,
          arg,
          (mySize & 0xff) | (signedKind(theirKind) ? 0x100 : 0),
        );
        return;
      }
      // A KIND THAT MOVED IS REPORTED AND NEVER REINTERPRETED (§4).
      report.kindMismatch++;
      return;
    }
    switch (myKind) {
      case 35: // the OPTIONAL wrapper: the present byte, then the payload
        push(plan, TableFixedOp.copy, theirAt, auxAt, 1, 0, guard, arg, 0);
        compileEntry(
          plan,
          ti + 1,
          theirAt + 1,
          mi + 1,
          dst,
          myAt,
          guard,
          arg,
          report,
          census,
        );
        break;
      case 13: // a nested table: match its fields
        matchChildren(
          plan,
          ti,
          theirAt,
          mi,
          dst,
          at,
          guard,
          arg,
          report,
          census,
        );
        break;
      case 14: // an array: the count, then min( their bound, my bound )
        final theirElem = theirs.size(ti + 1);
        final myElem = mine.size(mi + 1);
        final head = dst[row + TableFixedLane.dstCounted] != 0 ? 4 : 0;
        final theirN = theirElem != 0 ? (theirSize - head) ~/ theirElem : 0;
        final myN = myElem != 0 ? (mySize - head) ~/ myElem : 0;
        if (dst[row + TableFixedLane.dstCounted] != 0) {
          // THE COUNT'S BOUND IS THE WRITER'S, CARRIED BY THE PLAN (§5.2's
          // EMIT, bill §12.5): a count forged past what THIS ENDPOINT could have
          // written clamps and counts, and a count the reader merely has more
          // room for does not. A monotone lineage only ever grows a bound, so
          // the writer's is never the looser of the two.
          push(
            plan,
            TableFixedOp.count,
            theirAt,
            auxAt,
            theirN,
            0,
            guard,
            arg,
            0,
          );
        }
        final theirBase = theirAt + head;
        final elems = theirN < myN ? theirN : myN;
        for (var i = 0; i < elems; i++) {
          // THE CENSUS IS ONCE PER FIELD PER ENDPOINT (§5.4), never once per
          // ELEMENT: the four elements of an array are ONE field of ONE endpoint,
          // so only element 0 carries the census into the walk. A leg that
          // censuses every element lands the element count (§5.8 row 11).
          compileEntry(
            plan,
            ti + 1,
            theirBase + i * theirElem,
            mi + 1,
            dst,
            at + i * dst[row + TableFixedLane.dstStride],
            guard,
            arg,
            report,
            census && i == 0,
          );
        }
        break;
      case 16: // an enum-keyed array: every slot, matched by the KEY's id
        final theirKeys = theirs.children(ti + 1);
        final myKeys = mine.children(mi + 1);
        final theirElemAt = ti + 1 + theirs.subtree(ti + 1);
        final myElemAt = mi + 1 + mine.subtree(mi + 1);
        final theirElemSize = theirs.size(theirElemAt);
        for (var k = 0; k < myKeys; k++) {
          for (var j = 0; j < theirKeys; j++) {
            if (theirs.id(ti + 2 + j) != mine.id(mi + 2 + k)) {
              continue;
            }
            compileEntry(
              plan,
              theirElemAt,
              theirAt + j * theirElemSize,
              myElemAt,
              dst,
              at + k * dst[row + TableFixedLane.dstStride],
              guard,
              arg,
              report,
              census && k == 0,
            );
            break;
          }
        }
        break;
      case 15: // a union: the tag, remapped, then each arm matched by id
        final theirTag = theirs.tagBytes(ti);
        final myTag = mine.tagBytes(mi);
        // THE GUARD IS THE WRITER'S TAG AND IS COMPARED AT ITS WIDTH (§5.2).
        final savedArgw = plan.argw;
        plan.argw = (theirTag >= 1 && theirTag <= 8) ? theirTag : 1;
        final theirArms = theirs.children(ti);
        final myArms = mine.children(mi);
        // THE TAG'S "NONE" GOES DOWN FIRST AND UNGUARDED. Every tag value below
        // is written under THEIR tag's guard, so a record naming an arm this
        // build does not have — or a tag past the writer's arm set entirely —
        // would land NO TAG AT ALL, and the prefill cannot answer for it
        // because those bytes are named by the guarded entries. The image is
        // reused record to record, so what stood there was the PREVIOUS
        // record's arm. The plan is partitioned unguarded-first, so this is
        // overwritten by the arm that matches and stands when none does. It is
        // the one byte this form writes twice, and it is the compiled path's
        // alone.
        //
        // Nested: None answers to the OUTER tag at the OUTER width. push stamps
        // plan.argw, which is the INNER tag's width by now, so the outer width
        // is restored for this one entry.
        //
        // meta CARRIES THE WRITER'S ARM COUNT for this one entry — the plan
        // is private to a reader and not a wire structure, so the lane costs
        // nothing — and the read loop counts a clamp for a tag past that set
        // (§5.4: a hostile tag is counted on BOTH plans).
        final innerArgw = plan.argw;
        if (guard != tableFixedNoGuard) {
          plan.argw = savedArgw <= 0 ? 1 : savedArgw;
        }
        push(
          plan,
          TableFixedOp.constant,
          theirAt,
          auxAt,
          myTag,
          0,
          guard,
          arg,
          (theirArms >= 1 && theirArms <= 255) ? theirArms : 0,
        );
        plan.argw = innerArgw;
        var myArm = mi + 1;
        for (var k = 0; k < myArms; k++) {
          var theirArm = ti + 1;
          for (var j = 0; j < theirArms; j++) {
            if (theirs.id(theirArm) == mine.id(myArm)) {
              // THE ARM ANSWERS TO THIS TAG AND TO EVERY TAG OUTSIDE IT (§4.1,
              // the guard chain): one link pushed on the way in, the arm's own
              // tag const included, popped on the way out.
              if (plan.chainLen >= 65) {
                plan.overflow = true;
                return;
              }
              final savedAt = plan.chainAt;
              final l = plan.chainLen * 3;
              plan.chain[l] = theirAt;
              plan.chain[l + 1] = j + 1;
              plan.chain[l + 2] = plan.argw <= 0 ? 1 : plan.argw;
              plan.chainLen++;
              plan.chainAt = -1;
              // MY tag value, written under THEIR tag's guard
              push(
                plan,
                TableFixedOp.constant,
                theirAt,
                auxAt,
                myTag,
                k + 1,
                theirAt,
                j + 1,
                0,
              );
              compileEntry(
                plan,
                theirArm,
                theirAt + theirTag,
                myArm,
                dst,
                at,
                theirAt,
                j + 1,
                report,
                census,
              );
              plan.chainLen--;
              plan.chainAt = savedAt;
              break;
            }
            theirArm += theirs.subtree(theirArm);
          }
          myArm += mine.subtree(myArm);
        }
        plan.argw = savedArgw;
        break;
      case 30: // an enum: the ordinal is the layout's position, so it remaps
        // THE HALF IS TESTED BEFORE THE POOL SPENDS (§5.2, the two-pass split):
        // layRemap allocates ahead of its push, so the discarded pass would
        // spend the pool and a plan that fits would come back plan_too_large.
        if (!keeping(plan, guard)) {
          break;
        }
        // A GROWN ORDINAL WIDTH IS A WIDEN, unsigned, and it counts 'widened'
        // (§5.2's EMIT, bill §12.7): the names did not move, the width did.
        if (theirSize < mySize) {
          push(
            plan,
            TableFixedOp.widen,
            theirAt,
            at,
            theirSize,
            0,
            guard,
            arg,
            mySize & 0xff,
          );
          break;
        }
        final theirVariants = theirs.children(ti);
        final myVariants = mine.children(mi);
        final variants = theirVariants < 255 ? theirVariants : 255;
        for (var j = 0; j < variants; j++) {
          var landed = 0;
          for (var k = 0; k < myVariants; k++) {
            if (mine.id(mi + 1 + k) == theirs.id(ti + 1 + j)) {
              landed = k + 1;
              break;
            }
          }
          plan.remapScratch[j] = landed;
        }
        final remapAt = layRemap(plan, plan.remapScratch, variants);
        push(
          plan,
          TableFixedOp.ordinal,
          theirAt,
          at,
          theirSize,
          remapAt,
          guard,
          arg,
          mySize & 0xff,
        );
        break;
      case 12: // string(N)
        // SAME-SIZE TEXT IS A COPY: a counted array of wrapped strings
        // would otherwise TEXT every bound slot, and slack lengths would
        // count. The decode both paths share clamps LIVE used-lengths.
        // A bound that MOVED still needs the text op (min units).
        if (theirSize == mySize) {
          push(plan, TableFixedOp.copy, theirAt, at, mySize, 0, guard, arg, 0);
          break;
        }
        final units = (mySize - 4) < (theirSize - 4)
            ? (mySize - 4)
            : (theirSize - 4);
        push(
          plan,
          TableFixedOp.text,
          theirAt,
          at,
          units,
          auxAt,
          guard,
          arg,
          dst[row + TableFixedLane.dstArg],
        );
        break;
      default:
        if (theirSize == mySize) {
          push(plan, TableFixedOp.copy, theirAt, at, mySize, 0, guard, arg, 0);
        } else if (theirSize < mySize && mySize <= 8) {
          push(
            plan,
            TableFixedOp.widen,
            theirAt,
            at,
            theirSize,
            0,
            guard,
            arg,
            mySize & 0xff,
          );
        } else {
          report.kindMismatch++;
        }
        break;
    }
  }

  /// THE COALESCER, and it is the only optimization a plan compiler performs:
  /// two neighbouring COPY entries whose source and destination both advance
  /// together are one entry. It is performed identically on both sides.
  /// It runs ONCE PER HALF, from the index that half starts at: coalescing
  /// ACROSS the split would put a guarded entry's bytes under an unguarded run
  /// (§5.9 #42).
  static void coalesce(TableFixedPlan plan, int from) {
    final e = plan.entries;
    var out = from;
    for (var i = from; i < plan.count; i++) {
      final b = i * TableFixedLane.lanes;
      if (out > from) {
        final p = (out - 1) * TableFixedLane.lanes;
        if (e[p + TableFixedLane.op] == TableFixedOp.copy &&
            e[b + TableFixedLane.op] == TableFixedOp.copy &&
            e[p + TableFixedLane.guard] == e[b + TableFixedLane.guard] &&
            e[p + TableFixedLane.arg] == e[b + TableFixedLane.arg] &&
            e[p + TableFixedLane.argW] == e[b + TableFixedLane.argW] &&
            e[p + TableFixedLane.guards] == e[b + TableFixedLane.guards] &&
            e[p + TableFixedLane.guardCount] == e[b + TableFixedLane.guardCount] &&
            e[p + TableFixedLane.src] + e[p + TableFixedLane.size] ==
                e[b + TableFixedLane.src] &&
            e[p + TableFixedLane.dst] + e[p + TableFixedLane.size] ==
                e[b + TableFixedLane.dst]) {
          e[p + TableFixedLane.size] += e[b + TableFixedLane.size];
          continue;
        }
      }
      final o = out * TableFixedLane.lanes;
      for (var k = 0; k < TableFixedLane.lanes; k++) {
        e[o + k] = e[b + k];
      }
      out++;
    }
    plan.count = out;
  }

  /// TableFixedEntryLands is the bytes of the READER'S OWN IMAGE one entry
  /// writes — TWO runs, because a text entry lands a length and a buffer and
  /// every other op lands one run and leaves the second empty.
  ///
  /// A GUARDED ENTRY COUNTS AS LANDING ITS BYTES. It is a union arm, and an
  /// arm's storage is the arm's: the tag says which one is live and nothing
  /// reads the others. What must never be conditional is the TAG, and the
  /// compiler lays an unguarded one down for exactly this reason.
  static void entryLands(Int32List plan, int b, Int32List lands) {
    final dst = plan[b + TableFixedLane.dst];
    final size = plan[b + TableFixedLane.size];
    lands[0] = dst;
    lands[1] = dst;
    lands[2] = 0;
    lands[3] = 0;
    switch (plan[b + TableFixedLane.op]) {
      case TableFixedOp.count:
        lands[1] = dst + 4;
        break;
      case TableFixedOp.text:
        lands[1] = dst + 4;
        lands[2] = plan[b + TableFixedLane.aux];
        // Dart's image IS the wire: no terminator past the bound.
        lands[3] = lands[2] + size;
        break;
      case TableFixedOp.widenFloat:
        lands[1] = dst + 8;
        break;
      case TableFixedOp.widen:
      case TableFixedOp.ordinal:
        lands[1] = dst + (plan[b + TableFixedLane.meta] & 0xff);
        break;
      default:
        lands[1] = dst + size;
        break;
    }
  }

  /// fills is the subtraction: the cover MINUS everything the plan lands, as
  /// (dst, size) pairs packed into out. It runs once per compile, never per
  /// record. Guarded entries count as landing, so the identity plan's list is
  /// empty — that is the rule's limit case, not an exception to it.
  static int fills(
    Int32List plan,
    int count,
    Int32List cover,
    int coverCount,
    Int32List out,
  ) {
    var n = 0;
    final lands = Int32List(4);
    for (var r = 0; r < coverCount; r++) {
      final hi = cover[r * 2] + cover[r * 2 + 1];
      var pos = cover[r * 2];
      while (pos < hi) {
        var end = pos;
        var next = hi;
        for (var i = 0; i < count; i++) {
          entryLands(plan, i * TableFixedLane.lanes, lands);
          for (var q = 0; q < 4; q += 2) {
            final lo = lands[q];
            final top = lands[q + 1];
            if (top <= lo) {
              continue;
            }
            if (lo <= pos && pos < top) {
              if (top > end) {
                end = top;
              }
            } else if (lo > pos && lo < next) {
              next = lo;
            }
          }
        }
        if (end > pos) {
          pos = end;
          continue;
        }
        if (next > hi) {
          next = hi;
        }
        if (n * 2 + 1 < out.length) {
          out[n * 2] = pos;
          out[n * 2 + 1] = next - pos;
        }
        n++;
        pos = next;
      }
    }
    return n;
  }

  /// compile builds the plan for ANOTHER writer's layout against my own and
  /// answers how many entries it wrote, or -1 when it did not fit. The endpoint's
  /// layout must already have passed TableFixedLayout.parse. THE PREFILL'S
  /// RANGES are worked out here, once: the type's value bytes minus everything
  /// this plan lands.
  static int compile(
    TableFixedPlan plan,
    Uint8List myLayout,
    ByteData myLayoutView,
    Int32List myDst,
    Int32List cover,
    int coverCount,
    TableFixedReport report,
  ) {
    if (!plan.mine.parse(myLayoutView, 0, myLayout.length)) {
      return -1;
    }
    plan.count = 0;
    plan.chainLen = 0;
    plan.chainAt = -1;
    plan.remapUsed = 0;
    plan.overflow = false;
    plan.tooLarge = false;
    // THE WRITER'S DECLARED RECORD (§5.2's record := x.root.size): every
    // entry this compile pushes is bounded by it and by nothing the file
    // said. theirs is parsed by the caller, from the lock's own bytes.
    plan.record = plan.theirs.size(0);
    plan.fillCount = 0;
    plan.argw = 1;
    // PASS 1, UNGUARDED, COUNTING THE CENSUS. PASS 2, GUARDED, COUNTING
    // NOTHING (§5.2 PLAN, §5.9 #42): the census is once per endpoint, so a second
    // walk of the same pairs must not count them twice — the second report is
    // quiet and thrown away.
    plan.pass = 0;
    matchChildren(plan, 0, 0, 0, myDst, 0, tableFixedNoGuard, 0, report, true);
    coalesce(plan, 0);
    plan.split = plan.count;
    plan.pass = 1;
    plan.argw = 1;
    matchChildren(
      plan,
      0,
      0,
      0,
      myDst,
      0,
      tableFixedNoGuard,
      0,
      TableFixedReport(),
      false,
    );
    coalesce(plan, plan.split);
    plan.pass = 0;
    // -3 IS ONE ENTRY PAST THE WRITER'S RECORD (§5.2): the plan refused WHOLE
    // under layout_record_too_large, and no bigger room fixes it, so the
    // caller names the entry's lane rather than growing and retrying.
    if (plan.tooLarge) {
      return -3;
    }
    if (plan.overflow) {
      return -1;
    }
    plan.fillCount = fills(
      plan.entries,
      plan.count,
      cover,
      coverCount,
      plan.fill,
    );
    return plan.count;
  }
}


// ---------------------------------------------------------------------------
// THE MESSAGE FORM'S ANNOUNCEMENT, form byte 2 (docs/SPEC-TABLES.md §3.3)
// ---------------------------------------------------------------------------

/// ONE RECEIVED ANNOUNCEMENT per direction. "A failed first announcement is
/// terminal too; a second never changes its vocabulary or build version."
/// (§3.3). The storage the caller hands in is never replaced, so a resolved
/// vocabulary allocates nothing.
class TableVocabulary {
  List<TableMessageEntry> entries;
  int count = 0;
  int refBits = 1;
  int buildVersion = 0;
  bool announced = false;
  bool attempted = false;

  /// "THE ONE-ANNOUNCEMENT WORK BUDGET" (§3.3): the caller declares the bound
  /// the payload length and the entry count are held to.
  int maxEntries;
  int maxBytes;

  /// "STRICT MODE IS OPT-IN, and the default is unchanged." (§3.3).
  bool strict = false;

  /// THE RESERVED IDS the announcement's trailer names (§3.3), and the node
  /// table's, which a second entry may not name. They are members so nothing
  /// lands at library scope, the leg's own rule.
  static const int buildVersionWireId = -2; // 0xFFFFFFFFFFFFFFFE as signed
  static const int vocabularyWireId = -3; // 0xFFFFFFFFFFFFFFFD as signed
  static const int nodeWireId = -1; // 0xFFFFFFFFFFFFFFFF as signed

  TableVocabulary({
    required this.entries,
    this.maxEntries = 4096,
    this.maxBytes = 65536,
  });

  int get BuildVersion => buildVersion;
}

/// ONE ANNOUNCED ENTRY: an id, a kind, and a shape. The entry carries the
/// width facts a bitpacked body needs to step over a field it cannot name
/// (docs/SPEC-TABLES.md §3.3).
class TableMessageEntry {
  final int id;
  final int kind;
  /// The entry's wire bytes, its triple's identity: §3.3 lets one NAME appear
  /// at two shapes, so a repeated entry is the same bytes and not the same id.
  final Uint8List signature;
  TableMessageEntry(this.id, this.kind, [Uint8List? signature])
      : signature = signature ?? Uint8List(0);
}

/// THE REPORT the announcement read answers on. A refusal is terminal: it
/// sets 'refused' and 'reason' and nothing else moves.
class TableReport {
  bool refused = false;
  bool malformed = false;
  int unknown = 0;
  /// §4's other events, carried here so a message read answers the same
  /// six-counter report the Go reference does (internal/tabletext.Report).
  int kindMismatch = 0;
  int widened = 0;
  int clamped = 0;
  int duplicate = 0;
  int buildVersionRemote = 0;
  int buildVersionOwn = 0;
  String reason = '';
  /// The float whose raw bits a read found to be a NaN or an infinity, as
  /// <Table>.<field>, '' when it found none (docs/SPEC-TABLES.md §3.3).
  String nonFiniteFloat = '';

  void Damage() {
    malformed = true;
    reason = 'malformed';
  }

  bool Refuse(String why) {
    refused = true;
    reason = why;
    return false;
  }

  /// EVERY READ REFUSES A NaN OR AN INFINITY (docs/SPEC-TABLES.md §3.3), the
  /// tolerant batch read included: the reason names the field, and the batch
  /// lands nothing.
  bool RefuseNonFiniteFloat(String field) {
    nonFiniteFloat = field;
    return Refuse('non_finite_float: $field');
  }
}

/// "The ANNOUNCEMENT IS A COMPILE-TIME CONSTANT BYTE ARRAY WITH A LENGTH."
/// (§3.3) — the length, emitted beside the bytes.
int announceMeasure() => tableAnnouncementLength;

/// Copies the compiled announcement into the caller's buffer and answers its
/// length, or -1 when the buffer is too small. Nothing here allocates.
int announce(Uint8List buffer) {
  if (buffer.length < tableAnnouncementLength) {
    return -1;
  }
  buffer.setRange(0, tableAnnouncementLength, tableAnnouncement);
  return tableAnnouncementLength;
}

/// THE RESERVED IDS the announcement's trailer names live on TableVocabulary.

/// Reads one announcement into 'vocabulary'. "NO RE-ANNOUNCEMENT, EVER."
/// (§3.3): a vocabulary that already announced, or whose first announcement
/// was refused, answers 'second_announcement' and is terminal.
bool announceRead(TableVocabulary vocabulary, Uint8List bytes, TableReport report) {
  if (vocabulary.attempted) {
    return report.Refuse('second_announcement');
  }
  vocabulary.attempted = true;
  if (bytes.length == 0) {
    report.Damage();
    return false;
  }
  // "the FORM BYTE is a whole byte and is read FIRST" (§3.3): a form this
  // reader does not carry is a refusal by name and never damage.
  if (bytes[0] != 1) {
    return report.Refuse(bytes[0] == 2 ? 'message_form_as_file' : 'newer_form');
  }
  if (bytes.length < 9) {
    report.Damage();
    return false;
  }
  final view = ByteData.sublistView(bytes);
  // the trailer: a run of u64 ids and a u64 count at the very end
  final trailerCount = view.getUint64(bytes.length - 8, Endian.little);
  if (trailerCount > (bytes.length - 9) ~/ 8) {
    report.Damage();
    return false;
  }
  final end = bytes.length - 8 - trailerCount * 8;
  // A BODY'S REFERENCES RESOLVE against the trailer's ids, which begin here.
  final ids = <int>[];
  for (var i = end; i < end + trailerCount * 8; i += 8) {
    ids.add(view.getUint64(i, Endian.little));
  }
  for (var i = 0; i < ids.length; i++) {
    for (var j = 0; j < i; j++) {
      if (ids[i] == ids[j]) {
        report.Damage();
        return false;
      }
    }
  }
  // THE BODY walks references into those ids. THE TWO STRICT CHECKS: exactly
  // one build-version field and exactly one vocabulary field, both answered
  // 'malformed'.
  var at = 1;
  var versions = 0;
  var vocabularies = 0;
  var bodyEnd = end;
  var vocabularyStart = 0;
  var vocabularyLength = 0;
  var terminated = false;
  while (at < bodyEnd) {
    final ref = bytes[at];
    at += 1;
    if (ref == 0) {
      terminated = true;
      break;
    }
    if (ref > ids.length) {
      break;
    }
    if (at >= bodyEnd) {
      break;
    }
    final id = ids[ref - 1];
    final kind = bytes[at];
    at += 1;
    if (id == TableVocabulary.buildVersionWireId) {
      if (kind != 9 || at + 8 > bodyEnd) {
        break;
      }
      vocabulary.buildVersion = view.getUint64(at, Endian.little);
      at += 8;
      versions++;
    } else if (id == TableVocabulary.vocabularyWireId) {
      if (kind != 14) {
        break;
      }
      // THE FIELD IS LENGTH-PREFIXED (§3): its body is a LEB length, then the
      // element kind, then the vocabulary's own LEB length, then the entries.
      final fieldLength = tableMessageLeb(bytes, at, bodyEnd);
      if (!fieldLength.$3 || fieldLength.$1 < 0) {
        break;
      }
      at = fieldLength.$2;
      final fieldEnd = at + fieldLength.$1;
      if (fieldEnd > bodyEnd) {
        break;
      }
      final elementKind = bytes[at];
      at += 1;
      if (elementKind != 6) {
        break;
      }
      final length = tableMessageLeb(bytes, at, fieldEnd);
      if (!length.$3 || length.$1 < 0) {
        break;
      }
      at = length.$2;
      if (at + length.$1 != fieldEnd) {
        break;
      }
      if (length.$1 > vocabulary.maxBytes) {
        return report.Refuse('vocabulary_too_large');
      }
      vocabularyStart = at;
      vocabularyLength = length.$1;
      at += length.$1;
      vocabularies++;
    } else {
      // §3.3: "Every other field of its body is ordinary and tolerant, so an
      // unknown one is skipped and counted and the announcement can GAIN a
      // field in a later minor without a lockstep redeploy." Only a failed
      // strict check is malformed, so the payload is stepped over by its kind
      // and the walk continues; a payload that will not step is the one break.
      final skipped = tableMessageSkipField(bytes, at, bodyEnd, kind);
      if (skipped < 0) {
        break;
      }
      at = skipped;
      report.unknown++;
    }
  }
  if (!terminated || versions != 1 || vocabularies != 1) {
    report.Damage();
    return false;
  }
  if (vocabulary.strict && vocabulary.buildVersion != tableBuildVersion) {
    report.buildVersionRemote = vocabulary.buildVersion;
    report.buildVersionOwn = tableBuildVersion;
    return report.Refuse('build_version_mismatch');
  }
  // THE VOCABULARY PAYLOAD is a run of entries, each an id, a kind and a
  // shape. A payload longer than the caller's entry bound refuses by name.
  var vAt = vocabularyStart;
  final vEnd = vocabularyStart + vocabularyLength;
  var seen = 0;
  var nodeSeen = false;
  while (vAt < vEnd) {
    if (seen >= vocabulary.maxEntries) {
      return report.Refuse('vocabulary_too_large');
    }
    final start = vAt;
    final next = tableMessageEntryEnd(bytes, vAt, vEnd);
    if (next < 0) {
      report.Damage();
      return false;
    }
    final id = view.getUint64(vAt, Endian.little);
    final kind = bytes[vAt + 8];
    // §3.3: "THE TWO RESERVED IDS OF THE ANNOUNCEMENT ITSELF ARE NOT IN THE
    // VOCABULARY." An entry carrying one is malformed; the node table's id may
    // name at most one entry; a repeated entry is malformed too.
    if (id == TableVocabulary.buildVersionWireId ||
        id == TableVocabulary.vocabularyWireId ||
        (id == TableVocabulary.nodeWireId && nodeSeen)) {
      report.Damage();
      return false;
    }
    if (id == TableVocabulary.nodeWireId) {
      nodeSeen = true;
    }
    for (var i = 0; i < seen; i++) {
      if (tableMessageSameEntry(bytes, start, next, vocabulary.entries[i].signature)) {
        report.Damage();
        return false;
      }
    }
    vAt = next;
    vocabulary.entries[seen] = TableMessageEntry(id, kind, bytes.sublist(start, next));
    seen++;
  }
  vocabulary.count = seen;
  vocabulary.refBits = seen == 0 ? 1 : tableMessageBits(seen);
  vocabulary.announced = true;
  return true;
}

/// Steps over ONE entry: a u64 id, a kind byte, and the SHAPE the kind gives it
/// (docs/SPEC-TABLES.md §3.3). Answers the offset past the entry, or -1 where
/// the bytes run out or a kind is outside the closed set. This is the mirror of
/// ir.DecodeShape, so an entry's shape is stepped over by its kind and never
/// mistaken for the next entry.
int tableMessageEntryEnd(Uint8List bytes, int at, int end) {
  if (at + 9 > end) {
    return -1;
  }
  final kind = bytes[at + 8];
  if (!tableMessageKnownKind(kind)) {
    return -1;
  }
  var p = tableMessageShapeEnd(bytes, at + 9, end, kind);
  if (p < 0) {
    return -1;
  }
  if (kind == 14 || kind == 16) {
    if (p >= end) {
      return -1;
    }
    final elem = bytes[p];
    p += 1;
    if (!tableMessageKnownKind(elem) || elem == 12) {
      return -1;
    }
    p = tableMessageShapeEnd(bytes, p, end, elem);
    if (p < 0) {
      return -1;
    }
    if (elem == 14 || elem == 16) {
      if (p >= end) {
        return -1;
      }
      final inner = bytes[p];
      p += 1;
      if (!tableMessageKnownKind(inner) || inner == 12) {
        return -1;
      }
    }
  }
  return p;
}

/// Steps over one SHAPE, the width facts the kind names (docs/SPEC-TABLES.md
/// §3.3), mirroring ir.DecodeShape's lengths: a packing byte, then its width
/// and base, or a length, or an array's two counts. -1 where the bytes run out.
int tableMessageShapeEnd(Uint8List bytes, int at, int end, int kind) {
  if ((kind >= 2 && kind <= 10) || (kind >= 18 && kind <= 29)) {
    if (at >= end) {
      return -1;
    }
    final packing = bytes[at];
    at += 1;
    if (packing == 0) {
      return at;
    }
    if (packing == 1 && kind != 10) {
      // A WIDTH ABOVE THE KIND'S OWN DOMAIN IS A HOSTILE WIDTH, checked once
      // here and never again (ir.DecodeShape checks the width against TableMessageKindBits). The
      // value is read whole, so a width near 2^63 still trips this test rather
      // than wrapping into a small number.
      final n = tableMessageLeb(bytes, at, end);
      if (!n.$3 || n.$1 < 0 || n.$1 > tableMessageKindWidth(kind) * 8) {
        return -1;
      }
      at = n.$2;
      if (kind >= 18) {
        return at + 16 <= end ? at + 16 : -1;
      }
      // A RANGED BASE IS A WHOLE LEB VALUE, and a signed kind's is a zigzag
      // near 2^64 for a minimum near -2^63 (ir.DecodeShape's
      // tableMessageUnzigzag). The bit pattern may read back negative in a
      // Dart int; that is a value, never a failed read.
      final base = tableMessageLeb(bytes, at, end);
      return base.$3 ? base.$2 : -1;
    }
    if (packing == 2 && kind == 10) {
      return at + 12 <= end ? at + 12 : -1;
    }
    return -1;
  }
  if (kind == 12) {
    final n = tableMessageLeb(bytes, at, end);
    return (!n.$3 || n.$1 < 0) ? -1 : n.$2;
  }
  if (kind == 14 || kind == 16) {
    if (kind == 14) {
      final lo = tableMessageLeb(bytes, at, end);
      if (!lo.$3 || lo.$1 < 0) {
        return -1;
      }
      at = lo.$2;
    }
    final hi = tableMessageLeb(bytes, at, end);
    return (!hi.$3 || hi.$1 < 0) ? -1 : hi.$2;
  }
  return at;
}

/// tableMessageKnownKind reports whether a kind is one of the closed set.
bool tableMessageKnownKind(int kind) => kind <= 32;

/// tableMessageSameEntry reports whether ONE entry's wire bytes equal an
/// earlier entry's signature (docs/SPEC-TABLES.md §3.3): a repeated entry is
/// malformed, and the identity is the bytes because one name may carry two
/// shapes.
bool tableMessageSameEntry(Uint8List bytes, int start, int end, Uint8List signature) {
  if (end - start != signature.length) {
    return false;
  }
  for (var i = 0; i < signature.length; i++) {
    if (bytes[start + i] != signature[i]) {
      return false;
    }
  }
  return true;
}

/// tableMessageKindWidth is the fixed width of a scalar kind's payload, or 0
/// where the kind is not a fixed-width scalar (docs/SPEC-TABLES.md §3).
int tableMessageKindWidth(int kind) {
  switch (kind) {
    case 1:
    case 2:
    case 6:
    case 20:
    case 25:
      return 1;
    case 3:
    case 7:
    case 21:
    case 26:
      return 2;
    case 4:
    case 8:
    case 10:
    case 22:
    case 27:
      return 4;
    case 5:
    case 9:
    case 11:
    case 23:
    case 28:
      return 8;
    case 18:
    case 19:
    case 24:
    case 29:
      return 16;
    default:
      return 0;
  }
}

/// tableMessageSkipField steps over ONE unknown body field's payload by its
/// kind (docs/SPEC-TABLES.md §3.3), the reference's Skip(kind) rule: a
/// fixed-width scalar is its width, a reference or a union is a LEB, and a
/// length-prefixed slice — 12, 13, 14, 16, 31, 32 — is a LEB length then
/// that many bytes. Answers the offset past the payload, or -1
/// where the bytes run out or a kind this reader cannot step is named.
int tableMessageSkipField(Uint8List bytes, int at, int end, int kind) {
  final width = tableMessageKindWidth(kind);
  if (width != 0) {
    return at + width <= end ? at + width : -1;
  }
  switch (kind) {
    case 17:
    case 30:
      final v = tableMessageLeb(bytes, at, end);
      return (!v.$3 || v.$1 < 0) ? -1 : v.$2;
    case 12:
    case 13:
    case 14:
    case 16:
    case 31:
    case 32:
      final n = tableMessageLeb(bytes, at, end);
      if (!n.$3 || n.$1 < 0 || n.$2 + n.$1 > end) {
        return -1;
      }
      return n.$2 + n.$1;
    case 15:
      final arm = tableMessageLeb(bytes, at, end);
      if (!arm.$3 || arm.$1 < 0) {
        return -1;
      }
      if (arm.$1 == 0) {
        return arm.$2;
      }
      if (arm.$2 >= end) {
        return -1;
      }
      final n = tableMessageLeb(bytes, arm.$2 + 1, end);
      if (!n.$3 || n.$1 < 0 || n.$2 + n.$1 > end) {
        return -1;
      }
      return n.$2 + n.$1;
    default:
      return -1;
  }
}

/// tableMessageBits is the width of a reference into an n-entry vocabulary.
int tableMessageBits(int n) {
  var count = 0;
  while (n != 0) {
    count++;
    n >>= 1;
  }
  return count == 0 ? 1 : count;
}

/// LEB128, the canonical length every length of a file takes (§3). Answers the
/// value, the offset past it, and whether the bytes spelled one whole (the Go
/// reference's readLebBytes). A value above 2^63 reads back NEGATIVE in a Dart
/// int; that is the uint64's bit pattern, not a failure, and the flag is what
/// tells the two apart. A signed ranged base near -2^63 is exactly such a
/// value (ir.DecodeShape, tableMessageUnzigzag), so the base read must keep it.
(int, int, bool) tableMessageLeb(Uint8List bytes, int at, int end) {
  var value = 0;
  var shift = 0;
  while (at < end && shift < 64) {
    final b = bytes[at];
    at++;
    value |= (b & 0x7f) << shift;
    if ((b & 0x80) == 0) {
      return (value, at, true);
    }
    shift += 7;
  }
  return (0, at, false);
}
