/// TableEntity's storage. Allocated at construction and never replaced: a read
/// FILLS one of these, exactly as the packet reader fills a packet class.
final class TableEntity {
  int entityId = 0;
  int posX = 0;
  int posY = 0;
  int posZ = 0;
  int yaw = 0;
  int pitch = 0;
  int velX = 0;
  int velY = 0;
  int velZ = 0;
  int health = 0;
  TableWeapon weapon = TableWeapon.none;
  int damage = 0;
  bool moving = false;
  bool firing = false;
}

/// initTableEntity restores construction values in place, preserving storage.
void initTableEntity(TableEntity value) {
  value.entityId = 0;
  value.posX = 0;
  value.posY = 0;
  value.posZ = 0;
  value.yaw = 0;
  value.pitch = 0;
  value.velX = 0;
  value.velY = 0;
  value.velZ = 0;
  value.health = 0;
  value.weapon = TableWeapon.none;
  value.damage = 0;
  value.moving = false;
  value.firing = false;
}

/// TableStat's storage. Allocated at construction and never replaced: a read
/// FILLS one of these, exactly as the packet reader fills a packet class.
final class TableStat {
  int statId = 0;
  int delta = 0;
}

/// initTableStat restores construction values in place, preserving storage.
void initTableStat(TableStat value) {
  value.statId = 0;
  value.delta = 0;
}

/// TableMixed's storage. Allocated at construction and never replaced: a read
/// FILLS one of these, exactly as the packet reader fills a packet class.
final class TableMixed {
  int protocolMagic = 0;
  int sequence = 0;
  int ackSequence = 0;
  int ackBits = 0;
  int sessionId = 0;
  int clientId = 0;
  int nonce = 1;
  int worldTime = 0;
  int frameTick = 0;
  double serverTime = 0.0;
  final List<TableEntity> entities = List.generate(8, (_) => TableEntity());
  int entitiesCount = 1;
  final List<TableStat> stats = List.generate(80, (_) => TableStat());
  int statsCount = 0;
  final TableEvent gameEvent = TableEvent();
  final Uint8List loadout = Uint8List(4);
  final Uint8List playerName = Uint8List(15);
  int playerNameLength = 0;
  final Uint8List payload = Uint8List(16);
  int payloadLength = 0;
  double aimX = 0.0;
  double aimY = 0.0;
  double aimZ = 0.0;
  double recoil = 0.0;
  double drift = 0.0;
  int wideKey = 0;
  int flux = 0;
  double ping = 0.0;
  int crcHint = 0;
  bool hasExtra = false;
  int extra = 0;
  int idleTicks = 0;
}

/// initTableMixed restores construction values in place, preserving storage.
void initTableMixed(TableMixed value) {
  value.protocolMagic = 0;
  value.sequence = 0;
  value.ackSequence = 0;
  value.ackBits = 0;
  value.sessionId = 0;
  value.clientId = 0;
  value.nonce = 1;
  value.worldTime = 0;
  value.frameTick = 0;
  value.serverTime = 0.0;
  for (var i = 0; i < 8; i++) {
    initTableEntity(value.entities[i]);
  }
  value.entitiesCount = 1;
  for (var i = 0; i < 80; i++) {
    initTableStat(value.stats[i]);
  }
  value.statsCount = 0;
  zeroTableEvent(value.gameEvent);
  value.loadout.fillRange(0, 4, 0);
  value.playerName.fillRange(0, 15, 0);
  value.playerNameLength = 0;
  value.payload.fillRange(0, 16, 0);
  value.payloadLength = 0;
  value.aimX = 0.0;
  value.aimY = 0.0;
  value.aimZ = 0.0;
  value.recoil = 0.0;
  value.drift = 0.0;
  value.wideKey = 0;
  value.flux = 0;
  value.ping = 0.0;
  value.crcHint = 0;
  value.hasExtra = false;
  value.extra = 0;
  value.idleTicks = 0;
}

/// TableEntity's stores. Every offset is a constant of the type and nothing is
/// measured: on this form MeasureBody is a constant, not a walk.
void tableEntityFixedWriteBody(
  Uint8List bytes,
  ByteData view,
  int at,
  TableEntity value,
) {
  view.setUint32(at, value.entityId, Endian.little);
  view.setInt32(at + 4, value.posX, Endian.little);
  view.setInt32(at + 8, value.posY, Endian.little);
  view.setInt32(at + 12, value.posZ, Endian.little);
  view.setUint32(at + 16, value.yaw, Endian.little);
  view.setUint32(at + 20, value.pitch, Endian.little);
  view.setInt32(at + 24, value.velX, Endian.little);
  view.setInt32(at + 28, value.velY, Endian.little);
  view.setInt32(at + 32, value.velZ, Endian.little);
  view.setInt32(at + 36, value.health, Endian.little);
  view.setUint8(at + 40, value.weapon);
  view.setUint64(at + 41, value.damage, Endian.little);
  view.setUint8(at + 49, value.moving ? 1 : 0);
  view.setUint8(at + 50, value.firing ? 1 : 0);
}

/// TableEntity's loads, out of the reader's own image and into the value the
/// caller handed in — filled, never returned, as the packet reader is.
///
/// THE DECLARED BOUNDS ARE CHECKED HERE and nowhere else: a range clamps
/// and counts (docs/SPEC-TABLES.md §4), a union tag past the last arm and
/// an enum ordinal past the last variant land None and count. They are
/// straight line rather than plan entries, so the identity path and a
/// plan compiled from a stranger's layout hold the SAME bounds. A COUNTED
/// ARRAY WALKS ITS LIVE COUNT, never the bound: slack is never clamped.
void tableEntityFixedDecode(
  TableEntity value,
  Uint8List image,
  ByteData view,
  int at,
  TableFixedReport report,
) {
  value.entityId = view.getUint32(at, Endian.little);
  if (value.entityId > 4095) {
    // the bits(12) WIDTH clamp
    value.entityId = 4095;
    report.clamped++;
  }
  value.posX = view.getInt32(at + 4, Endian.little);
  if (value.posX < -16383) {
    value.posX = -16383;
    report.clamped++;
  } else if (value.posX > 16383) {
    value.posX = 16383;
    report.clamped++;
  }
  value.posY = view.getInt32(at + 8, Endian.little);
  if (value.posY < -16383) {
    value.posY = -16383;
    report.clamped++;
  } else if (value.posY > 16383) {
    value.posY = 16383;
    report.clamped++;
  }
  value.posZ = view.getInt32(at + 12, Endian.little);
  if (value.posZ < -16383) {
    value.posZ = -16383;
    report.clamped++;
  } else if (value.posZ > 16383) {
    value.posZ = 16383;
    report.clamped++;
  }
  value.yaw = view.getUint32(at + 16, Endian.little);
  if (value.yaw > 511) {
    // the bits(9) WIDTH clamp
    value.yaw = 511;
    report.clamped++;
  }
  value.pitch = view.getUint32(at + 20, Endian.little);
  if (value.pitch > 511) {
    // the bits(9) WIDTH clamp
    value.pitch = 511;
    report.clamped++;
  }
  value.velX = view.getInt32(at + 24, Endian.little);
  if (value.velX < -2048) {
    value.velX = -2048;
    report.clamped++;
  } else if (value.velX > 2047) {
    value.velX = 2047;
    report.clamped++;
  }
  value.velY = view.getInt32(at + 28, Endian.little);
  if (value.velY < -2048) {
    value.velY = -2048;
    report.clamped++;
  } else if (value.velY > 2047) {
    value.velY = 2047;
    report.clamped++;
  }
  value.velZ = view.getInt32(at + 32, Endian.little);
  if (value.velZ < -2048) {
    value.velZ = -2048;
    report.clamped++;
  } else if (value.velZ > 2047) {
    value.velZ = 2047;
    report.clamped++;
  }
  value.health = view.getInt32(at + 36, Endian.little);
  if (value.health < 0) {
    value.health = 0;
    report.clamped++;
  } else if (value.health > 1000) {
    value.health = 1000;
    report.clamped++;
  }
  value.weapon = TableWeapon(view.getUint8(at + 40));
  if (value.weapon > 15) {
    value.weapon = TableWeapon.none;
    report.clamped++;
  }
  value.damage = view.getUint64(at + 41, Endian.little);
  value.moving = view.getUint8(at + 49) != 0;
  value.firing = view.getUint8(at + 50) != 0;
}

/// TableStat's stores. Every offset is a constant of the type and nothing is
/// measured: on this form MeasureBody is a constant, not a walk.
void tableStatFixedWriteBody(
  Uint8List bytes,
  ByteData view,
  int at,
  TableStat value,
) {
  view.setUint32(at, value.statId, Endian.little);
  view.setInt32(at + 4, value.delta, Endian.little);
}

/// TableStat's loads, out of the reader's own image and into the value the
/// caller handed in — filled, never returned, as the packet reader is.
///
/// THE DECLARED BOUNDS ARE CHECKED HERE and nowhere else: a range clamps
/// and counts (docs/SPEC-TABLES.md §4), a union tag past the last arm and
/// an enum ordinal past the last variant land None and count. They are
/// straight line rather than plan entries, so the identity path and a
/// plan compiled from a stranger's layout hold the SAME bounds. A COUNTED
/// ARRAY WALKS ITS LIVE COUNT, never the bound: slack is never clamped.
void tableStatFixedDecode(
  TableStat value,
  Uint8List image,
  ByteData view,
  int at,
  TableFixedReport report,
) {
  value.statId = view.getUint32(at, Endian.little);
  if (value.statId > 255) {
    // the bits(8) WIDTH clamp
    value.statId = 255;
    report.clamped++;
  }
  value.delta = view.getInt32(at + 4, Endian.little);
  if (value.delta < -512) {
    value.delta = -512;
    report.clamped++;
  } else if (value.delta > 511) {
    value.delta = 511;
    report.clamped++;
  }
}

/// TableHitEvent's stores. Every offset is a constant of the type and nothing is
/// measured: on this form MeasureBody is a constant, not a walk.
void tableHitEventFixedWriteBody(
  Uint8List bytes,
  ByteData view,
  int at,
  TableHitEvent value,
) {
  view.setUint32(at, value.targetId, Endian.little);
  view.setInt32(at + 4, value.damage, Endian.little);
  view.setInt32(at + 8, value.hitKind, Endian.little);
  view.setUint8(at + 12, value.crit ? 1 : 0);
}

/// TableHitEvent's loads, out of the reader's own image and into the value the
/// caller handed in — filled, never returned, as the packet reader is.
///
/// THE DECLARED BOUNDS ARE CHECKED HERE and nowhere else: a range clamps
/// and counts (docs/SPEC-TABLES.md §4), a union tag past the last arm and
/// an enum ordinal past the last variant land None and count. They are
/// straight line rather than plan entries, so the identity path and a
/// plan compiled from a stranger's layout hold the SAME bounds. A COUNTED
/// ARRAY WALKS ITS LIVE COUNT, never the bound: slack is never clamped.
void tableHitEventFixedDecode(
  TableHitEvent value,
  Uint8List image,
  ByteData view,
  int at,
  TableFixedReport report,
) {
  value.targetId = view.getUint32(at, Endian.little);
  if (value.targetId > 4095) {
    // the bits(12) WIDTH clamp
    value.targetId = 4095;
    report.clamped++;
  }
  value.damage = view.getInt32(at + 4, Endian.little);
  if (value.damage < 0) {
    value.damage = 0;
    report.clamped++;
  } else if (value.damage > 4095) {
    value.damage = 4095;
    report.clamped++;
  }
  value.hitKind = view.getInt32(at + 8, Endian.little);
  if (value.hitKind < 0) {
    value.hitKind = 0;
    report.clamped++;
  } else if (value.hitKind > 7) {
    value.hitKind = 7;
    report.clamped++;
  }
  value.crit = view.getUint8(at + 12) != 0;
}

/// TableChatEvent's stores. Every offset is a constant of the type and nothing is
