    value.channel = 3;
    report.clamped++;
  }
  value.speaker = view.getUint32(at + 4, Endian.little);
  if (value.speaker > 4095) {
    // the bits(12) WIDTH clamp
    value.speaker = 4095;
    report.clamped++;
  }
