/// TableMixed's stores. Every offset is a constant of the type and nothing is
/// measured: on this form MeasureBody is a constant, not a walk.
void tableMixedFixedWriteBody(
  Uint8List bytes,
  ByteData view,
  int at,
  TableMixed value,
) {
  view.setUint16(at, value.protocolMagic, Endian.little);
  view.setUint32(at + 2, value.sequence, Endian.little);
  view.setInt32(at + 6, value.ackSequence, Endian.little);
  view.setUint32(at + 10, value.ackBits, Endian.little);
  view.setUint64(at + 14, value.sessionId, Endian.little);
  view.setUint32(at + 22, value.clientId, Endian.little);
  view.setUint64(at + 26, value.nonce, Endian.little);
  view.setInt64(at + 34, value.worldTime, Endian.little);
  view.setUint64(at + 42, value.frameTick, Endian.little);
  view.setUint32(
    at + 50,
    TableFixedLayout.float32Bits(value.serverTime),
    Endian.little,
  );
  assert(value.entitiesCount >= 0);
  assert(value.entitiesCount <= 8);
  view.setInt32(at + 54, value.entitiesCount, Endian.little);
  for (var i = 0; i < value.entitiesCount; i++) {
    tableEntityFixedWriteBody(bytes, view, at + 58 + i * 51, value.entities[i]);
  }
  assert(value.statsCount >= 0);
  assert(value.statsCount <= 80);
  view.setInt32(at + 466, value.statsCount, Endian.little);
  for (var i = 0; i < value.statsCount; i++) {
    tableStatFixedWriteBody(bytes, view, at + 470 + i * 8, value.stats[i]);
  }
  view.setUint8(at + 1110, value.gameEvent.type);
  switch (value.gameEvent.type) {
    case 1:
      tableHitEventFixedWriteBody(bytes, view, at + 1111, value.gameEvent.hit);
      break;
    case 2:
      tableChatEventFixedWriteBody(
        bytes,
        view,
        at + 1111,
        value.gameEvent.chat,
      );
      break;
    case 3:
      tablePickupEventFixedWriteBody(
        bytes,
        view,
        at + 1111,
        value.gameEvent.pickup,
      );
      break;
    default:
      break;
  }
  bytes.setRange(at + 1124, at + 1124 + 4, value.loadout);
  assert(value.playerNameLength >= 0);
  assert(value.playerNameLength <= 15);
  view.setInt32(at + 1128, value.playerNameLength, Endian.little);
  bytes.setRange(
    at + 1132,
    at + 1132 + value.playerNameLength,
    value.playerName,
  );
  bytes.fillRange(at + 1132 + value.playerNameLength, at + 1147, 0);
  assert(value.payloadLength >= 0);
  assert(value.payloadLength <= 16);
  view.setInt32(at + 1147, value.payloadLength, Endian.little);
  bytes.setRange(at + 1151, at + 1151 + value.payloadLength, value.payload);
  bytes.fillRange(at + 1151 + value.payloadLength, at + 1167, 0);
  view.setUint32(
    at + 1167,
    TableFixedLayout.float32Bits(value.aimX),
    Endian.little,
  );
  view.setUint32(
    at + 1171,
    TableFixedLayout.float32Bits(value.aimY),
    Endian.little,
  );
  view.setUint32(
    at + 1175,
    TableFixedLayout.float32Bits(value.aimZ),
    Endian.little,
  );
  view.setUint32(
    at + 1179,
    TableFixedLayout.float32Bits(value.recoil),
    Endian.little,
  );
  view.setFloat64(at + 1183, value.drift, Endian.little);
  view.setUint64(at + 1191, value.wideKey, Endian.little);
  view.setInt64(at + 1199, value.flux, Endian.little);
  view.setUint32(
    at + 1207,
    TableFixedLayout.float32Bits(value.ping),
    Endian.little,
  );
  view.setUint32(at + 1211, value.crcHint, Endian.little);
  view.setUint8(at + 1215, value.hasExtra ? 1 : 0);
  view.setInt32(at + 1216, value.extra, Endian.little);
  view.setInt32(at + 1220, value.idleTicks, Endian.little);
}

/// TableMixed's loads, out of the reader's own image and into the value the
/// caller handed in — filled, never returned, as the packet reader is.
///
/// THE DECLARED BOUNDS ARE CHECKED HERE and nowhere else: a range clamps
/// and counts (docs/SPEC-TABLES.md §4), a union tag past the last arm and
/// an enum ordinal past the last variant land None and count. They are
/// straight line rather than plan entries, so the identity path and a
/// plan compiled from a stranger's layout hold the SAME bounds. A COUNTED
/// ARRAY WALKS ITS LIVE COUNT, never the bound: slack is never clamped.
void tableMixedFixedDecode(
  TableMixed value,
  Uint8List image,
  ByteData view,
  int at,
  TableFixedReport report,
) {
  value.protocolMagic = view.getUint16(at, Endian.little);
  value.sequence = view.getUint32(at + 2, Endian.little);
  if (value.sequence > 65535) {
    // the bits(16) WIDTH clamp
    value.sequence = 65535;
    report.clamped++;
  }
  value.ackSequence = view.getInt32(at + 6, Endian.little);
  if (value.ackSequence < 0) {
    value.ackSequence = 0;
    report.clamped++;
  } else if (value.ackSequence > 65535) {
    value.ackSequence = 65535;
    report.clamped++;
  }
  value.ackBits = view.getUint32(at + 10, Endian.little);
  value.sessionId = view.getUint64(at + 14, Endian.little);
  value.clientId = view.getUint32(at + 22, Endian.little);
  value.nonce = view.getUint64(at + 26, Endian.little);
  if ((value.nonce ^ 0x8000000000000000) < 0x8000000000000001) {
    value.nonce = 1;
    report.clamped++;
  } else if ((value.nonce ^ 0x8000000000000000) > 0xffffffffffffffff) {
    value.nonce = 9223372036854775807;
    report.clamped++;
  }
  value.worldTime = view.getInt64(at + 34, Endian.little);
  if (value.worldTime < -1000000000000) {
    value.worldTime = -1000000000000;
    report.clamped++;
  } else if (value.worldTime > 1000000000000) {
    value.worldTime = 1000000000000;
    report.clamped++;
  }
  value.frameTick = view.getUint64(at + 42, Endian.little);
  if ((value.frameTick ^ 0x8000000000000000) > 0x8000ffffffffffff) {
    // the bits(48) WIDTH clamp
    value.frameTick = 281474976710655;
    report.clamped++;
  }
  {
    final bits = view.getUint32(at + 50, Endian.little);
    if ((bits & 0x7f800000) == 0x7f800000) {
      report.refuseNonFiniteFloat('TableMixed.server_time');
    } else {
      value.serverTime = TableFixedLayout.float32Value(bits);
      if (value.serverTime < 0.0) {
        value.serverTime = 0.0;
        report.clamped++;
      } else if (value.serverTime > 65535.0) {
        value.serverTime = 65535.0;
        report.clamped++;
      } else if (value.serverTime == 0) {
        value.serverTime = 0.0;
      }
    }
  }
  value.entitiesCount = view.getInt32(at + 54, Endian.little);
  for (var i = 0; i < value.entitiesCount; i++) {
    tableEntityFixedDecode(
      value.entities[i],
      image,
      view,
      at + 58 + i * 51,
      report,
    );
  }
  value.statsCount = view.getInt32(at + 466, Endian.little);
  for (var i = 0; i < value.statsCount; i++) {
    tableStatFixedDecode(value.stats[i], image, view, at + 470 + i * 8, report);
  }
  value.gameEvent.type = TableEventType(view.getUint8(at + 1110));
  switch (value.gameEvent.type) {
    case 0:
      break; // None, which is a tag this reader holds
    case 1:
      tableHitEventFixedDecode(
        value.gameEvent.hit,
        image,
        view,
        at + 1111,
        report,
      );
      break;
    case 2:
      tableChatEventFixedDecode(
        value.gameEvent.chat,
        image,
        view,
        at + 1111,
        report,
      );
      break;
    case 3:
      tablePickupEventFixedDecode(
        value.gameEvent.pickup,
        image,
        view,
        at + 1111,
        report,
      );
      break;
    default:
      value.gameEvent.type = TableEventType.none;
      report.clamped++;
      break;
  }
  value.loadout.setRange(0, 4, image, at + 1124);
  value.playerNameLength = view.getInt32(at + 1128, Endian.little);
  if (value.playerNameLength < 0) {
    value.playerNameLength = 0;
    report.clamped++;
  } else if (value.playerNameLength > 15) {
    value.playerNameLength = 15;
    report.clamped++;
  }
  value.playerName.setRange(0, 15, image, at + 1132);
  value.payloadLength = view.getInt32(at + 1147, Endian.little);
  if (value.payloadLength < 0) {
    value.payloadLength = 0;
    report.clamped++;
  } else if (value.payloadLength > 16) {
    value.payloadLength = 16;
    report.clamped++;
  }
  value.payload.setRange(0, 16, image, at + 1151);
  {
    final bits = view.getUint32(at + 1167, Endian.little);
    if ((bits & 0x7f800000) == 0x7f800000) {
      report.refuseNonFiniteFloat('TableMixed.aim_x');
    } else {
      value.aimX = TableFixedLayout.float32Value(bits);
      if (value.aimX < -1.0) {
        value.aimX = -1.0;
        report.clamped++;
      } else if (value.aimX > 1.0) {
        value.aimX = 1.0;
        report.clamped++;
      } else if (value.aimX == 0) {
        value.aimX = 0.0;
      }
    }
  }
  {
    final bits = view.getUint32(at + 1171, Endian.little);
    if ((bits & 0x7f800000) == 0x7f800000) {
      report.refuseNonFiniteFloat('TableMixed.aim_y');
    } else {
      value.aimY = TableFixedLayout.float32Value(bits);
      if (value.aimY < -1.0) {
        value.aimY = -1.0;
        report.clamped++;
      } else if (value.aimY > 1.0) {
        value.aimY = 1.0;
        report.clamped++;
      } else if (value.aimY == 0) {
        value.aimY = 0.0;
      }
    }
  }
  {
    final bits = view.getUint32(at + 1175, Endian.little);
    if ((bits & 0x7f800000) == 0x7f800000) {
      report.refuseNonFiniteFloat('TableMixed.aim_z');
    } else {
      value.aimZ = TableFixedLayout.float32Value(bits);
      if (value.aimZ < -1.0) {
        value.aimZ = -1.0;
        report.clamped++;
      } else if (value.aimZ > 1.0) {
        value.aimZ = 1.0;
        report.clamped++;
      } else if (value.aimZ == 0) {
        value.aimZ = 0.0;
      }
    }
  }
  {
    final bits = view.getUint32(at + 1179, Endian.little);
    if ((bits & 0x7f800000) == 0x7f800000) {
      report.refuseNonFiniteFloat('TableMixed.recoil');
    } else {
      value.recoil = TableFixedLayout.float32Value(bits);
    }
  }
  {
    final bits = view.getUint64(at + 1183, Endian.little);
    if ((bits & 0x7ff0000000000000) == 0x7ff0000000000000) {
      report.refuseNonFiniteFloat('TableMixed.drift');
    } else {
      value.drift = view.getFloat64(at + 1183, Endian.little);
    }
  }
  value.wideKey = view.getUint64(at + 1191, Endian.little);
  value.flux = view.getInt64(at + 1199, Endian.little);
  if (value.flux < -1000000000000000000) {
    value.flux = -1000000000000000000;
    report.clamped++;
  } else if (value.flux > 1000000000000000000) {
    value.flux = 1000000000000000000;
    report.clamped++;
  }
  {
    final bits = view.getUint32(at + 1207, Endian.little);
    if ((bits & 0x7f800000) == 0x7f800000) {
      report.refuseNonFiniteFloat('TableMixed.ping');
    } else {
      value.ping = TableFixedLayout.float32Value(bits);
      if (value.ping < 0.0) {
        value.ping = 0.0;
        report.clamped++;
      } else if (value.ping > 250.0) {
        value.ping = 250.0;
        report.clamped++;
      } else if (value.ping == 0) {
        value.ping = 0.0;
      }
    }
  }
  value.crcHint = view.getUint32(at + 1211, Endian.little);
  if (value.crcHint > 16777215) {
    // the bits(24) WIDTH clamp
    value.crcHint = 16777215;
    report.clamped++;
  }
  value.hasExtra = view.getUint8(at + 1215) != 0;
  value.extra = view.getInt32(at + 1216, Endian.little);
  if (value.extra < 0) {
    value.extra = 0;
    report.clamped++;
  } else if (value.extra > 255) {
    value.extra = 255;
    report.clamped++;
  }
  value.idleTicks = view.getInt32(at + 1220, Endian.little);
  if (value.idleTicks < 0) {
    value.idleTicks = 0;
    report.clamped++;
  } else if (value.idleTicks > 15) {
    value.idleTicks = 15;
    report.clamped++;
  }
}

/// TableMixed's finite pass (docs/SPEC-TABLES.md §3.3): the first NaN or
/// infinity a save would carry, as <Owner>.<field>, or '' for none.
String tableMixedFixedFiniteBody(TableMixed value) {
  if (!value.serverTime.isFinite) return 'TableMixed.server_time';
  if (!value.aimX.isFinite) return 'TableMixed.aim_x';
  if (!value.aimY.isFinite) return 'TableMixed.aim_y';
  if (!value.aimZ.isFinite) return 'TableMixed.aim_z';
  if (!value.recoil.isFinite) return 'TableMixed.recoil';
  if (!value.drift.isFinite) return 'TableMixed.drift';
  if (!value.ping.isFinite) return 'TableMixed.ping';
  return '';
}

// ---- TableEntity, THE FIXED FORM (docs/SPEC-TABLES.md §3.4) ----
//
// A record is an eight-byte hash of the writer's LAYOUT and then the values
// in declared order, every field at its declared storage width, little-
// endian, nothing padded between fields.

/// MeasureBody IS A CONSTANT on this form: the body is the same size for
/// every value the type can hold.
const int tableEntityFixedBodyBytes = 51;
const int tableEntityFixedRecordBytes = 59; // the hash and the body

/// fnv1a64 over the layout's bytes exactly as written. A Dart int is a full
/// 64-bit two's complement value, so the hash rides as itself.
const int tableEntityFixedHash = 0x45d64db53ce7ac1f;

/// THE LAYOUT: 30 entries, a PRE-ORDER walk of the closure in the writer's
/// declared order. Every byte is settled by the compiler.
// dart format off
final Uint8List tableEntityFixedLayout = Uint8List.fromList(const <int>[
  0x1e, 0x00, 0x00, 0x00, 0xa8, 0xcb, 0xc6, 0x96, 0x35, 0x72, 0x61, 0x31,
  0x0d, 0x33, 0x00, 0x00, 0x00, 0x0e, 0x00, 0x00, 0x00, 0x12, 0x67, 0xe3,
  0x78, 0x66, 0xfd, 0xfc, 0x23, 0x07, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x0e, 0x31, 0x67, 0x76, 0x35, 0x37, 0x4b, 0xcb, 0x04, 0x04,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xc1, 0x32, 0x67, 0x76, 0x35,
  0x38, 0x4b, 0xcb, 0x04, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0xa8, 0x2d, 0x67, 0x76, 0x35, 0x35, 0x4b, 0xcb, 0x04, 0x04, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0xe8, 0x16, 0x8e, 0x79, 0x19, 0x8e, 0x4d,
  0xb5, 0x07, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xb1, 0xc1,
  0x0c, 0xa9, 0x65, 0xf6, 0xa9, 0x53, 0x07, 0x04, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x67, 0xee, 0x60, 0xeb, 0xb6, 0xe6, 0xed, 0x6c, 0x04,
  0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xb4, 0xec, 0x60, 0xeb,
