  if (hash != tableEntityFixedHash) {
    final lane = tableEntityFixedLineagePlans[pick];
    if (lane.why != TableFixedRefusal.none) {
      report.refused = lane.why;
      return -1;
    }
    // THE CALLER'S PLAN STAYS A CAPACITY DECLARATION and is no longer
    // written through (§5.9 #5): the entry count is checked against it and
    // a plan past it refuses by name.
    if (lane.count > plan.capacity) {
      report.refused = TableFixedRefusal.planTooLarge;
      return -1;
    }
    entries = lane.entries;
    entryCount = lane.count;
    fills = lane.fill;
    fillCount = lane.fillCount;
    remap = lane.remap;
    censusUnknown = lane.unknown;
    censusKind = lane.kindMismatch;
  }
  // THE HEADER NAMES THE LAYOUT ONCE. Identity memcmps the file's layout
  // against this build's; digest is not on the wire, so the header hash is
  // not a hash of the layout bytes alone (§3, bill §13).
  final rest = byteLength - TableFixedLimits.layoutAt - layoutBytes;
  // BYTES LEFT OVER ARE malformed, which is §3's rule for the same reason:
  // the two ends of the file have met.
  if (recordBytes <= 8 || rest % recordBytes != 0) {
    report.malformed = true;
    return -1;
  }
  final n = rest ~/ recordBytes;
  if (n > capacity) {
    report.refused = TableFixedRefusal.batchTooLarge;
    return -1;
  }
  var at = TableFixedLimits.layoutAt + layoutBytes;
  // A RECORD WHOSE HASH NAMES NO LAYOUT THIS READER HOLDS IS A REFUSAL BY
  // NAME, never a guess and never damage: nothing is decoded and no
  // counter moves. EVERY record's hash is held to it BEFORE the first is
  // decoded, because REFUSE is total (§5.3): not one destination byte is
  // written, so a bad later record cannot follow good earlier ones in.
  for (var k = 0, probe = at; k < n; k++, probe += recordBytes) {
    if (view.getUint64(probe, Endian.little) != hash) {
      report.refused = TableFixedRefusal.noLayout;
      return -1;
    }
  }
  for (var k = 0; k < n; k++) {
    tableFixedFillRun(fills, fillCount, tableEntityFixedPrefill, plan.image);
    // THE RUN NAMES ITS OWN REFUSAL (§4.5 fix 11): a text entry whose USED
    // units are ill-formed comes back as `text_ill_formed`, and the whole
    // read refuses BY NAME — nothing is decoded past it, and the entry that
    // violated the rule moved no counter and wrote no byte.
    final runWhy = tableFixedRun(
      entries,
      entryCount,
      bytes,
      view,
      at + 8,
      plan.image,
      plan.imageView,
      remap,
      plan.conv,
      report,
    );
    if (runWhy != TableFixedRefusal.none) {
      report.refused = runWhy;
      return -1;
    }
    tableEntityFixedDecode(values[k], plan.image, plan.imageView, 0, report);
    at += recordBytes;
  }
  // THE CENSUS LANDS ONCE, HERE, on a read that returns (§5.4, §5.9 #6).
  report.unknown += censusUnknown;
  report.kindMismatch += censusKind;
  return n;
}

// ---- TableEntity, THE MESSAGE FORM's BATCH (docs/SPEC-TABLES.md §3.3) ----
/// MeasureMessages sizes the buffer for a batch of TableEntity bodies, or -1 with
/// the reason on the report (docs/SPEC-TABLES.md §3.3).
int tableEntityMeasureMessages(List<TableEntity> values, TableReport report) {
  if (values.length < 1 || values.length > tableMessageBatchMax) {
    report.Refuse('batch_too_large');
    return -1;
  }
  final w = TableBitWriter(Uint8List(0))..measuring = true;
  for (final value in values) {
    if (!tableEntitySaveMessageBody(w, value)) return -1;
  }
  w.align();
  if (w.overflow) return -1;
  return 2 + (w.bits >> 3);
}

/// SaveMessages writes one buffer for a batch of TableEntity bodies, or -1 with
/// the reason on the report (docs/SPEC-TABLES.md §3.3).
int tableEntitySaveMessages(
  List<TableEntity> values,
  Uint8List buffer,
  TableReport report,
) {
  if (values.length < 1 || values.length > tableMessageBatchMax) {
    report.Refuse('batch_too_large');
    return -1;
  }
  if (buffer.length < 2) return -1;
  buffer[0] = 2;
  buffer[1] = values.length - 1;
  final w = TableBitWriter(Uint8List.sublistView(buffer, 2));
  for (final value in values) {
    if (!tableEntitySaveMessageBody(w, value)) return -1;
  }
  w.align();
  if (w.overflow) return -1;
  return 2 + (w.bits >> 3);
}

/// LoadMessages reads one buffer into the caller's storage, allocating
/// nothing, and answers the bodies read (docs/SPEC-TABLES.md §3.3).
int tableEntityLoadMessages(
  List<TableEntity> values,
  Uint8List bytes,
  TableVocabulary vocabulary,
  TableReport report,
) {
  final r = TableMessageReader();
  final count = tableMessageBatchOpen(vocabulary, bytes, report, r);
  if (count < 0) return -1;
  if (count > values.length) {
    report.Refuse('batch_too_large');
    return count;
  }
  for (var i = 0; i < count; i++) {
    if (!tableEntityLoadMessageBody(r, values[i])) {
      if (report.nonFiniteFloat.isEmpty) return i;
      for (var j = 0; j <= i; j++) {
        initTableEntity(values[j]);
      }
      return 0;
    }
  }
  if (!tableMessageBatchClose(r)) return count;
  return count;
}

// ---- TableStat, THE FIXED FORM (docs/SPEC-TABLES.md §3.4) ----
//
// A record is an eight-byte hash of the writer's LAYOUT and then the values
// in declared order, every field at its declared storage width, little-
// endian, nothing padded between fields.

/// MeasureBody IS A CONSTANT on this form: the body is the same size for
/// every value the type can hold.
const int tableStatFixedBodyBytes = 8;
const int tableStatFixedRecordBytes = 16; // the hash and the body

/// fnv1a64 over the layout's bytes exactly as written. A Dart int is a full
/// 64-bit two's complement value, so the hash rides as itself.
const int tableStatFixedHash = 0x1cdc2a66a7601422;

/// THE LAYOUT: 3 entries, a PRE-ORDER walk of the closure in the writer's
/// declared order. Every byte is settled by the compiler.
// dart format off
final Uint8List tableStatFixedLayout = Uint8List.fromList(const <int>[
  0x03, 0x00, 0x00, 0x00, 0x95, 0x9c, 0xb9, 0x69, 0xe6, 0xa8, 0x6a, 0x29,
  0x0d, 0x08, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00, 0x65, 0xbf, 0x6d,
  0x86, 0xf0, 0x75, 0xab, 0x80, 0x06, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0xc1, 0xa0, 0x13, 0xec, 0x75, 0x66, 0x07, 0x52, 0x04, 0x04,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
]);
// dart format on
const int tableStatFixedLayoutBytes = 55;

/// A FILE'S WHOLE HEAD: §3's sixteen-byte HEADER — the form byte, seven
/// reserved zero bytes and the LAYOUT HASH at 8 — then the layout's u32
/// length and the layout itself. The records begin here.
const int tableStatFixedHeaderBytes = 75;

/// THE PREFILL: the declared defaults as a constant run of bytes. A field
/// this record does not carry has no plan entry, so it keeps what this put
/// there and the loop never learns it existed. THE LOAD COPIES ONLY THE
/// RANGES THE PLAN DOES NOT LAND — identity's list is empty.
// dart format off
final Uint8List tableStatFixedPrefill = Uint8List.fromList(const <int>[
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
]);
// dart format on

/// THE TYPE'S VALUE BYTES: every byte of this build's own image that holds
/// a DECLARED VALUE, sorted and merged. THE PREFILL IS THIS SET MINUS WHAT
/// A PLAN LANDS (§3.4), so against the identity plan it is empty and the
/// identity read writes no byte twice; a plan compiled from a stranger's
/// layout subtracts itself from it once, when the plan is compiled, and
/// prefills exactly the rest.
// dart format off
final Int32List tableStatFixedCover = Int32List.fromList(const <int>[
  0, 8,
]);
// dart format on
const int tableStatFixedCoverCount = 1;

/// MY SIDE of the layout, five lanes per entry: the storage facts a layout
/// entry cannot carry. In C++ these are offsetof rows; the reader's own
/// storage in Dart is the canonical image, so they are its offsets.
// dart format off
final Int32List tableStatFixedDst = Int32List.fromList(const <int>[
  0, 0, 0, 0, 0, // 0 TableStat
  0, 0, 0, 0, 0, // 1 stat_id
  4, 0, 0, 0, 0, // 2 delta
]);
// dart format on

/// THE IDENTITY PLAN, coalesced HERE rather than at run time: when a record's
/// hash is this build's own the plan is the one the compiler already wrote.
/// Because the reader's own storage in this language IS the wire's layout,
/// source and destination advance together and the walk collapses to 1
/// entry — the same coalescer the plan compiler runs, reaching its best case
/// rather than skipping a step. A COUNT and a TEXT LENGTH keep entries of
/// their own, because those two are the only bytes a record does not merely
/// move: a hostile one is CLAMPED to this reader's bound before it reaches a
/// value a consumer will index with.
// dart format off
final Int32List tableStatFixedIdentity = Int32List.fromList(const <int>[
  0, 0, 0, 8, 0, -1, 0, 0, 1, 0, 0,
]);
// dart format on
const int tableStatFixedIdentityCount = 1;

/// THE GUARD CHAIN'S POOL for the identity plan (§4.1): offset+count from an
/// entry's guards lanes, (guard, arg, argw) a link, outermost first.
// dart format off
final Int32List tableStatFixedIdentityGuards = Int32List.fromList(const <int>[
]);
// dart format on

/// THE SPLIT: the index the identity plan's GUARDED half starts at — the
/// number of unguarded entries (docs/FIXED-FORM-ALGORITHM.md §4.1, §4.4,
/// §5.9 #42). Every entry below it carries no guard and every entry at or
/// above it carries one; the run loop tests the guard per entry, which #42
/// allows, but the plan is still partitioned and states its split.
const int tableStatFixedIdentitySplit = 1;

/// THE LINEAGE: every layout of TableStat this build serves, OLDEST FIRST and
/// THE CURRENT ONE LAST (§5.2). A file is matched on its header's hash
/// against these and on nothing else; the layout it carries is COMPARED
/// with the bytes the lock recorded and never parsed. A hash no entry holds
/// is `layout_newer` — ship the reader.
// dart format off
final List<TableFixedKnownLayout> tableStatFixedKnown = <TableFixedKnownLayout>[
  TableFixedKnownLayout(0x1cdc2a66a7601422, Uint8List.fromList(const <int>[
  0x03, 0x00, 0x00, 0x00, 0x95, 0x9c, 0xb9, 0x69, 0xe6, 0xa8, 0x6a, 0x29,
  0x0d, 0x08, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00, 0x65, 0xbf, 0x6d,
  0x86, 0xf0, 0x75, 0xab, 0x80, 0x06, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0xc1, 0xa0, 0x13, 0xec, 0x75, 0x66, 0x07, 0x52, 0x04, 0x04,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  ]), 55, 16),
];
// dart format on

/// THE FLOOR: 1 + the highest RETIRED index, 0 when none is (§5.2). Below
/// it a layout this build once served is retired and the answer is
/// `layout_unsupported` — upgrade the client — rather than `layout_newer`.
const int tableStatFixedFloor = 0;

/// ONE PLAN PER LINEAGE ENTRY, built from THE LOCK'S bytes the first time
/// this list is read and never again (§5.9 #3): nothing on the load path
/// compiles, nothing on it parses a layout a file carried, and the load
/// cannot fail for want of a plan.
final List<TableFixedLineagePlan> tableStatFixedLineagePlans =
    tableFixedLineagePlans(
      tableStatFixedKnown,
      tableStatFixedLayout,
      tableStatFixedDst,
      tableStatFixedCover,
      tableStatFixedCoverCount,
      tableStatFixedBodyBytes,
      tableStatFixedHash,
    );

/// THE PLAN'S STORAGE IS THE CALLER'S, DECLARED BY CAPACITY, AND THE CODEC
/// NEVER ALLOCATES. One of these per endpoint; a layout whose plan does not fit
/// is a refusal by name.
TableFixedPlan tableStatFixedNewPlan({
  int entryCapacity = 4096,
  int remapCapacity = 4096,
}) {
  return TableFixedPlan(entryCapacity, tableStatFixedBodyBytes, remapCapacity);
}

/// A FILE: §3's sixteen-byte HEADER, the layout behind its u32 length, then
/// the records to the end of it. A FILE ALWAYS CARRIES THE LAYOUT — a file is
/// read by somebody who was not there when it was written.
int tableStatFixedMeasure(int count) {
  return tableStatFixedHeaderBytes + count * tableStatFixedRecordBytes;
}

final tableStatFixedSaveView = TableFixedView();

/// THE WRITE IS A TEMPLATE: the hash and zeros laid down first — which is
/// also what zero-fills every byte of declared slack — and then value stores
/// at constant offsets. No measuring pass, no id interning, no trailer and no
/// second walk. Answers the bytes written, or -1; nothing here throws.
int tableStatFixedSave(List<TableStat> values, int count, Uint8List bytes) {
  final need = tableStatFixedMeasure(count);
  if (count < 0 || bytes.length < need) {
    return -1;
  }
  final view = tableStatFixedSaveView.of(bytes);
  // THE HEADER, ONE RULE FOR ALL FIVE FORMS (§3): the form byte, seven
  // RESERVED ZERO bytes, the LAYOUT HASH at 8, and the body at 16.
  bytes.fillRange(0, TableFixedLimits.headerBytes, 0);
  bytes[0] = tableFixedForm;
  view.setUint64(TableFixedLimits.hashAt, tableStatFixedHash, Endian.little);
  view.setUint32(
    TableFixedLimits.headerBytes,
    tableStatFixedLayoutBytes,
    Endian.little,
  );
  bytes.setRange(
    TableFixedLimits.layoutAt,
    tableStatFixedHeaderBytes,
    tableStatFixedLayout,
  );
  var at = tableStatFixedHeaderBytes;
  for (var k = 0; k < count; k++) {
    view.setUint64(at, tableStatFixedHash, Endian.little);
    // the template's zeros, which is also every byte of declared slack
    bytes.fillRange(at + 8, at + tableStatFixedRecordBytes, 0);
    tableStatFixedWriteBody(bytes, view, at + 8, values[k]);
    at += tableStatFixedRecordBytes;
  }
  return need;
}

final tableStatFixedLoadView = TableFixedView();

/// THE READ: a prefill and ONE loop over ONE plan — the identity plan when
/// the layout's hash is this build's own, and a plan compiled once from the
/// writer's layout otherwise. THE SAME LOOP EITHER WAY: there is no strict
/// flag, no fast path and no second reader to keep honest against the first,
/// which is the owner's own ruling — a form whose cost moved when an endpoint
/// shipped would be a cliff at exactly the moment a deployment cannot afford
/// one.
///
/// THE PREFILL IS EXACTLY THE BYTES THE PLAN DOES NOT LAND. It is a list of
/// ranges the plan compiler works out once, and on the identity plan that
/// list is EMPTY — so this read writes no byte twice, and it is one rule for
/// both plans rather than a flag that asks which one this is. Answers the
/// records read, or -1 with the reason named in the report.
int tableStatFixedLoad(
  List<TableStat> values,
  int capacity,
  Uint8List bytes,
  int byteLength,
  TableFixedPlan plan,
  TableFixedReport report,
) {
  report.reset();
  if (byteLength < 1 || byteLength > bytes.length) {
    report.malformed = true;
    return -1;
  }
  final view = tableStatFixedLoadView.of(bytes);
  // THE FORM BYTE IS READ FIRST, AND IT SAYS WHICH DIRECTION (§3, §3.4):
  // the registry is ordered, so a byte this reader does not carry is named
  // by where it sits relative to this form and never by one word for both.
  // AND IT IS READ BEFORE THE FILE'S LENGTH (§5.3): a committed form-1 file
  // is TEN bytes and a form-2 batch THREE, so a reader that measured first
  // would answer `malformed` for every real file of the two forms it names.
  if (bytes[0] != tableFixedForm) {
    report.refused = switch (bytes[0]) {
      TableFixedLimits.variableForm => TableFixedRefusal.previousForm,
      TableFixedLimits.messageForm => TableFixedRefusal.messageFormAsFile,
      _ => TableFixedRefusal.newerForm,
    };
    return -1;
  }
  if (byteLength < TableFixedLimits.layoutAt) {
    report.malformed = true;
    return -1;
  }
  // THE SEVEN RESERVED BYTES ARE REFUSED, NOT IGNORED (§3.4, §5.3).
  for (var i = 1; i < TableFixedLimits.hashAt; i++) {
    if (bytes[i] != 0) {
      report.malformed = true;
      return -1;
    }
  }
  final layoutBytes = view.getUint32(
    TableFixedLimits.headerBytes,
    Endian.little,
  );
  if (layoutBytes + TableFixedLimits.layoutAt > byteLength) {
    report.refused = TableFixedRefusal.layoutMalformed;
    return -1;
  }
  final hash = view.getUint64(TableFixedLimits.hashAt, Endian.little);
  // THE LINEAGE SELECT (§5.3 steps 5 and 6): the header's hash is taken as
  // GIVEN — the digest is not on the wire, so it cannot be re-derived from a
  // file — and it is matched against the layouts THE LOCK recorded. Nothing
  // parses a stranger's layout, on any path.
  final pick = tableFixedSelect(tableStatFixedKnown, hash);
  if (pick < 0) {
    report.layoutHash = hash;
    report.refused = TableFixedRefusal.layoutNewer;
    return -1;
  }
  if (pick < tableStatFixedFloor) {
    report.layoutHash = hash;
    report.refused = TableFixedRefusal.layoutUnsupported;
    return -1;
  }
  // THE BYTES THE LOCK RECORDED, compared and never walked: every §1.1
  // malformation under a KNOWN hash is one name, layout_malformed.
  final known = tableStatFixedKnown[pick];
  if (layoutBytes != known.layoutBytes) {
    report.refused = TableFixedRefusal.layoutMalformed;
    return -1;
  }
  for (var i = 0; i < layoutBytes; i++) {
    if (bytes[TableFixedLimits.layoutAt + i] != known.layout[i]) {
      report.refused = TableFixedRefusal.layoutMalformed;
      return -1;
    }
  }
  report.hash = hash; // the header's hash; digest is not on the wire
  // THE PLAN THIS ENDPOINT RESOLVES TO, and the record size FROM THE LOCK and
  // never from the file.
  var entries = tableStatFixedIdentity;
  var entryCount = tableStatFixedIdentityCount;
  var recordBytes = known.recordBytes;
  var fills = plan.fill;
  // THE PREFILL'S RANGES. EMPTY ON THE IDENTITY PLAN, and not by a flag:
  // the rule is the type's value bytes minus what the plan lands, and the
  // identity plan lands all of them.
  var fillCount = 0;
  var remap = tableStatFixedIdentityGuards;
  // THE COMPILE CENSUS IS THE PLAN'S OWN NUMBERS, carried onto the report
  // ONCE after the record loop and only on a read that returns (§5.9 #6):
  // once per endpoint, never per record, and REFUSE moves no counter at all.
  var censusUnknown = 0;
  var censusKind = 0;
  if (hash != tableStatFixedHash) {
    final lane = tableStatFixedLineagePlans[pick];
    if (lane.why != TableFixedRefusal.none) {
      report.refused = lane.why;
      return -1;
    }
    // THE CALLER'S PLAN STAYS A CAPACITY DECLARATION and is no longer
    // written through (§5.9 #5): the entry count is checked against it and
    // a plan past it refuses by name.
    if (lane.count > plan.capacity) {
      report.refused = TableFixedRefusal.planTooLarge;
      return -1;
    }
    entries = lane.entries;
    entryCount = lane.count;
    fills = lane.fill;
    fillCount = lane.fillCount;
    remap = lane.remap;
    censusUnknown = lane.unknown;
    censusKind = lane.kindMismatch;
  }
  // THE HEADER NAMES THE LAYOUT ONCE. Identity memcmps the file's layout
  // against this build's; digest is not on the wire, so the header hash is
  // not a hash of the layout bytes alone (§3, bill §13).
  final rest = byteLength - TableFixedLimits.layoutAt - layoutBytes;
  // BYTES LEFT OVER ARE malformed, which is §3's rule for the same reason:
  // the two ends of the file have met.
  if (recordBytes <= 8 || rest % recordBytes != 0) {
    report.malformed = true;
    return -1;
  }
  final n = rest ~/ recordBytes;
  if (n > capacity) {
    report.refused = TableFixedRefusal.batchTooLarge;
    return -1;
  }
  var at = TableFixedLimits.layoutAt + layoutBytes;
  // A RECORD WHOSE HASH NAMES NO LAYOUT THIS READER HOLDS IS A REFUSAL BY
  // NAME, never a guess and never damage: nothing is decoded and no
  // counter moves. EVERY record's hash is held to it BEFORE the first is
  // decoded, because REFUSE is total (§5.3): not one destination byte is
  // written, so a bad later record cannot follow good earlier ones in.
  for (var k = 0, probe = at; k < n; k++, probe += recordBytes) {
    if (view.getUint64(probe, Endian.little) != hash) {
      report.refused = TableFixedRefusal.noLayout;
      return -1;
    }
  }
  for (var k = 0; k < n; k++) {
    tableFixedFillRun(fills, fillCount, tableStatFixedPrefill, plan.image);
    // THE RUN NAMES ITS OWN REFUSAL (§4.5 fix 11): a text entry whose USED
    // units are ill-formed comes back as `text_ill_formed`, and the whole
    // read refuses BY NAME — nothing is decoded past it, and the entry that
    // violated the rule moved no counter and wrote no byte.
    final runWhy = tableFixedRun(
      entries,
      entryCount,
      bytes,
      view,
      at + 8,
      plan.image,
      plan.imageView,
      remap,
      plan.conv,
      report,
    );
    if (runWhy != TableFixedRefusal.none) {
      report.refused = runWhy;
      return -1;
    }
    tableStatFixedDecode(values[k], plan.image, plan.imageView, 0, report);
    at += recordBytes;
  }
  // THE CENSUS LANDS ONCE, HERE, on a read that returns (§5.4, §5.9 #6).
  report.unknown += censusUnknown;
  report.kindMismatch += censusKind;
  return n;
}

// ---- TableStat, THE MESSAGE FORM's BATCH (docs/SPEC-TABLES.md §3.3) ----
/// MeasureMessages sizes the buffer for a batch of TableStat bodies, or -1 with
/// the reason on the report (docs/SPEC-TABLES.md §3.3).
int tableStatMeasureMessages(List<TableStat> values, TableReport report) {
  if (values.length < 1 || values.length > tableMessageBatchMax) {
    report.Refuse('batch_too_large');
    return -1;
  }
  final w = TableBitWriter(Uint8List(0))..measuring = true;
  for (final value in values) {
    if (!tableStatSaveMessageBody(w, value)) return -1;
  }
  w.align();
  if (w.overflow) return -1;
  return 2 + (w.bits >> 3);
}

/// SaveMessages writes one buffer for a batch of TableStat bodies, or -1 with
/// the reason on the report (docs/SPEC-TABLES.md §3.3).
int tableStatSaveMessages(
  List<TableStat> values,
  Uint8List buffer,
  TableReport report,
) {
  if (values.length < 1 || values.length > tableMessageBatchMax) {
    report.Refuse('batch_too_large');
    return -1;
  }
  if (buffer.length < 2) return -1;
  buffer[0] = 2;
  buffer[1] = values.length - 1;
  final w = TableBitWriter(Uint8List.sublistView(buffer, 2));
  for (final value in values) {
    if (!tableStatSaveMessageBody(w, value)) return -1;
  }
  w.align();
  if (w.overflow) return -1;
  return 2 + (w.bits >> 3);
}

/// LoadMessages reads one buffer into the caller's storage, allocating
/// nothing, and answers the bodies read (docs/SPEC-TABLES.md §3.3).
int tableStatLoadMessages(
  List<TableStat> values,
  Uint8List bytes,
  TableVocabulary vocabulary,
  TableReport report,
) {
  final r = TableMessageReader();
  final count = tableMessageBatchOpen(vocabulary, bytes, report, r);
  if (count < 0) return -1;
  if (count > values.length) {
    report.Refuse('batch_too_large');
    return count;
  }
  for (var i = 0; i < count; i++) {
    if (!tableStatLoadMessageBody(r, values[i])) {
      if (report.nonFiniteFloat.isEmpty) return i;
      for (var j = 0; j <= i; j++) {
        initTableStat(values[j]);
      }
      return 0;
    }
  }
  if (!tableMessageBatchClose(r)) return count;
  return count;
}

// ---- TableMixed, THE FIXED FORM (docs/SPEC-TABLES.md §3.4) ----
//
// A record is an eight-byte hash of the writer's LAYOUT and then the values
// in declared order, every field at its declared storage width, little-
// endian, nothing padded between fields.

/// MeasureBody IS A CONSTANT on this form: the body is the same size for
/// every value the type can hold.
const int tableMixedFixedBodyBytes = 1224;
const int tableMixedFixedRecordBytes = 1232; // the hash and the body

/// fnv1a64 over the layout's bytes exactly as written. A Dart int is a full
/// 64-bit two's complement value, so the hash rides as itself.
